/* AquaGest Pro — migrações estruturais do IndexedDB. */
(function () {
  "use strict";

  var OFFICIAL_VERSION = 6;

  function upgrade(db, oldVersion, newVersion, transaction) {
    if (!db || !transaction) {
      throw new Error("Transação de migração indisponível.");
    }

    if (oldVersion < 5 && newVersion >= 5 && db.objectStoreNames.contains("schema_migrations")) {
      transaction.objectStore("schema_migrations").put({
        id: "migration-v5-structure-and-recovery",
        migrationId: "migration-v5-structure-and-recovery",
        schemaVersion: 5,
        status: "completed",
        description: "Versão oficial do banco para backup, recuperação de estoque e consistência dos relatórios.",
        executedAt: new Date().toISOString()
      });
    }

    if (oldVersion < 6 && newVersion >= 6 && db.objectStoreNames.contains("schema_migrations")) {
      transaction.objectStore("schema_migrations").put({
        id: "migration-v6-health-records",
        migrationId: "migration-v6-health-records",
        schemaVersion: 6,
        status: "completed",
        description: "Inclui registros estruturados de sanidade por lote e viveiro.",
        executedAt: new Date().toISOString()
      });
    }
  }

  window.AquaGestMigrations = {
    OFFICIAL_VERSION: OFFICIAL_VERSION,
    upgrade: upgrade
  };
})();

;

