/* ===== js/core/app-state.js ===== */
// @ts-nocheck

/*
  AquaGest Pro
  Arquivo: js/core/app-state.js
  Etapa: infraestrutura central de estado
  Versão: app-state-v5-desempenho-integrado
  Status:
  - sessão local robusta
  - localStorage protegido
  - navegação validada
  - Desempenho reconhecido
  - tema resiliente
  - inicialização idempotente
  - compatibilidade preservada com AuthService e app.js
*/

(function () {
  "use strict";

  var SESSION_KEY =
    "aquagestpro_session";

  var THEME_KEY =
    "aquagestpro_theme";

  var THEME_CHOICE_KEY =
    "aquagestpro_theme_choice";

  var SCREEN_KEY =
    "aquagestpro_current_screen";

  var SESSION_VERSION = 1;

  var SESSION_MAX_AGE_DAYS = 30;

  /*
    Tolerância para relógio do dispositivo
    adiantado em relação ao savedAt.
  */
  var MAX_FUTURE_CLOCK_SKEW_MS =
    24 * 60 * 60 * 1000;

  /*
    ============================================================
    TELAS VÁLIDAS
    ============================================================
  */

  var VALID_SCREENS = [
    "dashboard",
    "piscicultura",
    "viveiros",
    "producao",
    "biometria",
    "previsoes",
    "sanidade",
    "desempenho",
    "agua",
    "arracoamento",
    "estoque",
    "financeiro",
    "relatorios",
    "configuracoes"
  ];

  /*
    ============================================================
    ESTADO CENTRAL
    ============================================================
  */

  var state = {
    currentUser: null,

    currentPropertyId: null,

    currentScreen:
      "dashboard",

    theme:
      "light",

    initialized:
      false,

    initializedAt:
      null,

    lastSessionLoadedAt:
      null
  };

  /*
    ============================================================
    UTILITÁRIOS
    ============================================================
  */

  function nowIso() {
    return new Date()
      .toISOString();
  }

  function normalizeText(value) {
    if (
      value === null ||
      value === undefined
    ) {
      return "";
    }

    return String(value)
      .trim();
  }

  function normalizeEmail(value) {
    return normalizeText(value)
      .toLowerCase();
  }

  function normalizeNullableText(value) {
    var text =
      normalizeText(value);

    return text || null;
  }

  function normalizeRole(value) {
    var role =
      normalizeText(value)
        .toLowerCase();

    return role || "owner";
  }

  function normalizeStatus(value) {
    var status =
      normalizeText(value)
        .toLowerCase();

    return status || "active";
  }

  function normalizeSessionVersion(value) {
    var version =
      Number(value);

    if (
      !Number.isFinite(version) ||
      version < 1
    ) {
      return SESSION_VERSION;
    }

    return Math.floor(
      version
    );
  }

  /*
    ============================================================
    TELAS
    ============================================================
  */

  function normalizeScreenName(
    screenName
  ) {
    return normalizeText(
      screenName
    ).toLowerCase();
  }

  function isValidScreen(
    screenName
  ) {
    var cleanScreen =
      normalizeScreenName(
        screenName
      );

    return (
      VALID_SCREENS.indexOf(
        cleanScreen
      ) !== -1
    );
  }

  function normalizeScreen(
    screenName
  ) {
    var cleanScreen =
      normalizeScreenName(
        screenName
      );

    return isValidScreen(
      cleanScreen
    )
      ? cleanScreen
      : "dashboard";
  }

  /*
    ============================================================
    LOCAL STORAGE SEGURO
    ============================================================
  */

  function storageGet(key) {
    try {
      if (
        !window.localStorage
      ) {
        return null;
      }

      return window.localStorage
        .getItem(
          key
        );
    } catch (error) {
      console.warn(
        "[AquaGest Pro] Não foi possível ler o armazenamento local:",
        error
      );

      return null;
    }
  }

  function storageSet(
    key,
    value
  ) {
    try {
      if (
        !window.localStorage
      ) {
        return false;
      }

      window.localStorage
        .setItem(
          key,
          String(value)
        );

      return true;
    } catch (error) {
      console.warn(
        "[AquaGest Pro] Não foi possível gravar no armazenamento local:",
        error
      );

      return false;
    }
  }

  function storageRemove(key) {
    try {
      if (
        !window.localStorage
      ) {
        return false;
      }

      window.localStorage
        .removeItem(
          key
        );

      return true;
    } catch (error) {
      console.warn(
        "[AquaGest Pro] Não foi possível remover dado do armazenamento local:",
        error
      );

      return false;
    }
  }

  /*
    ============================================================
    USUÁRIO DE SESSÃO
    ============================================================
  */

  function sanitizeUser(user) {
    if (
      !user ||
      typeof user !== "object"
    ) {
      return null;
    }

    return {
      id:
        normalizeNullableText(
          user.id
        ),

      name:
        normalizeText(
          user.name
        ),

      email:
        normalizeEmail(
          user.email
        ),

      role:
        normalizeRole(
          user.role
        ),

      propertyId:
        normalizeNullableText(
          user.propertyId
        ),

      status:
        normalizeStatus(
          user.status
        )
    };
  }

  function isValidSessionUser(user) {
    return !!(
      user &&
      normalizeText(
        user.id
      ) &&
      normalizeText(
        user.email
      ) &&
      normalizeText(
        user.role
      ) &&
      normalizeStatus(
        user.status
      ) === "active"
    );
  }

  /*
    ============================================================
    EXPIRAÇÃO DE SESSÃO
    ============================================================
  */

  function isSessionExpired(
    savedAt
  ) {
    var cleanSavedAt =
      normalizeText(
        savedAt
      );

    if (
      !cleanSavedAt
    ) {
      return true;
    }

    var savedTime =
      new Date(
        cleanSavedAt
      ).getTime();

    if (
      !Number.isFinite(
        savedTime
      )
    ) {
      return true;
    }

    var currentTime =
      Date.now();

    /*
      Evita aceitar sessão com data
      excessivamente no futuro.
    */
    if (
      savedTime >
      currentTime +
        MAX_FUTURE_CLOCK_SKEW_MS
    ) {
      return true;
    }

    var maxAgeMs =
      SESSION_MAX_AGE_DAYS *
      24 *
      60 *
      60 *
      1000;

    return (
      currentTime -
      savedTime >
      maxAgeMs
    );
  }

  /*
    ============================================================
    SESSÃO
    ============================================================
  */

  function buildSessionPayload() {
    if (
      !state.currentUser
    ) {
      return null;
    }

    return {
      user:
        sanitizeUser(
          state.currentUser
        ),

      propertyId:
        normalizeNullableText(
          state.currentPropertyId
        ),

      savedAt:
        nowIso(),

      version:
        SESSION_VERSION
    };
  }

  function persistSession() {
    if (
      !state.currentUser
    ) {
      storageRemove(
        SESSION_KEY
      );

      return false;
    }

    var payload =
      buildSessionPayload();

    if (
      !payload
    ) {
      return false;
    }

    try {
      return storageSet(
        SESSION_KEY,
        JSON.stringify(
          payload
        )
      );
    } catch (error) {
      console.warn(
        "[AquaGest Pro] Não foi possível serializar a sessão:",
        error
      );

      return false;
    }
  }

  function clearSession() {
    state.currentUser =
      null;

    state.currentPropertyId =
      null;

    state.lastSessionLoadedAt =
      null;

    storageRemove(
      SESSION_KEY
    );
  }

  function loadSession() {
    var raw =
      storageGet(
        SESSION_KEY
      );

    if (
      !raw
    ) {
      state.currentUser =
        null;

      state.currentPropertyId =
        null;

      state.lastSessionLoadedAt =
        null;

      return null;
    }

    try {
      var session =
        JSON.parse(
          raw
        );

      if (
        !session ||
        typeof session !==
          "object"
      ) {
        clearSession();

        return null;
      }

      if (
        isSessionExpired(
          session.savedAt
        )
      ) {
        clearSession();

        return null;
      }

      var user =
        sanitizeUser(
          session.user
        );

      if (
        !isValidSessionUser(
          user
        )
      ) {
        clearSession();

        return null;
      }

      var sessionPropertyId =
        normalizeNullableText(
          session.propertyId
        );

      var userPropertyId =
        normalizeNullableText(
          user.propertyId
        );

      state.currentUser =
        user;

      state.currentPropertyId =
        sessionPropertyId ||
        userPropertyId ||
        null;

      /*
        Mantém usuário e propriedade sincronizados
        em memória.
      */
      state.currentUser.propertyId =
        state.currentPropertyId;

      state.lastSessionLoadedAt =
        nowIso();

      return {
        user:
          getCurrentUser(),

        propertyId:
          getCurrentPropertyId(),

        savedAt:
          normalizeText(
            session.savedAt
          ),

        version:
          normalizeSessionVersion(
            session.version
          )
      };
    } catch (error) {
      console.warn(
        "[AquaGest Pro] Sessão local inválida.",
        error
      );

      clearSession();

      return null;
    }
  }

  function saveSession(user) {
    var cleanUser =
      sanitizeUser(
        user
      );

    if (
      !isValidSessionUser(
        cleanUser
      )
    ) {
      clearSession();

      throw new Error(
        "Usuário de sessão inválido."
      );
    }

    /*
      Se a atualização do usuário não trouxer
      propertyId, preserva a Piscicultura
      já selecionada para o mesmo usuário.
    */
    var existingPropertyId =
      state.currentUser &&
      String(
        state.currentUser.id ||
        ""
      ) ===
        String(
          cleanUser.id ||
          ""
        )
        ? state.currentPropertyId
        : null;

    var propertyId =
      normalizeNullableText(
        cleanUser.propertyId
      ) ||
      normalizeNullableText(
        existingPropertyId
      ) ||
      null;

    cleanUser.propertyId =
      propertyId;

    state.currentUser =
      cleanUser;

    state.currentPropertyId =
      propertyId;

    persistSession();

    return {
      user:
        getCurrentUser(),

      propertyId:
        getCurrentPropertyId()
    };
  }

  function refreshSession() {
    if (
      !state.currentUser
    ) {
      return null;
    }

    if (
      !isValidSessionUser(
        state.currentUser
      )
    ) {
      clearSession();

      return null;
    }

    persistSession();

    return {
      user:
        getCurrentUser(),

      propertyId:
        getCurrentPropertyId()
    };
  }

  /*
    ============================================================
    USUÁRIO ATUAL
    ============================================================
  */

  function getCurrentUser() {
    if (
      !state.currentUser
    ) {
      return null;
    }

    return sanitizeUser(
      state.currentUser
    );
  }

  /*
    ============================================================
    PISCICULTURA ATUAL
    ============================================================
  */

  function getCurrentPropertyId() {
    var propertyId =
      normalizeNullableText(
        state.currentPropertyId
      );

    if (
      propertyId
    ) {
      return propertyId;
    }

    if (
      state.currentUser &&
      state.currentUser.propertyId
    ) {
      return normalizeNullableText(
        state.currentUser.propertyId
      );
    }

    return null;
  }

  function setCurrentPropertyId(
    propertyId
  ) {
    var cleanPropertyId =
      normalizeNullableText(
        propertyId
      );

    state.currentPropertyId =
      cleanPropertyId;

    if (
      state.currentUser
    ) {
      state.currentUser.propertyId =
        cleanPropertyId;

      persistSession();
    }

    return cleanPropertyId;
  }

  /*
    ============================================================
    TELA ATUAL
    ============================================================
  */

  function setCurrentScreen(
    screenName
  ) {
    var cleanScreen =
      normalizeScreen(
        screenName
      );

    state.currentScreen =
      cleanScreen;

    storageSet(
      SCREEN_KEY,
      cleanScreen
    );

    return cleanScreen;
  }

  function getCurrentScreen() {
    return normalizeScreen(
      state.currentScreen
    );
  }

  function loadCurrentScreen() {
    var savedScreen =
      storageGet(
        SCREEN_KEY
      );

    var cleanScreen =
      normalizeScreen(
        savedScreen
      );

    state.currentScreen =
      cleanScreen;

    /*
      Corrige valor antigo/inválido salvo.
    */
    if (
      savedScreen !==
      cleanScreen
    ) {
      storageSet(
        SCREEN_KEY,
        cleanScreen
      );
    }

    return cleanScreen;
  }

  /*
    ============================================================
    TEMA
    ============================================================
  */

  function normalizeTheme(theme) {
    return theme ===
      "dark"
      ? "dark"
      : "light";
  }

  /*
    v25: o app abre sempre no tema claro. O tema escuro só é usado quando o
    produtor escolhe "Alternar tema"; a escolha fica salva em THEME_CHOICE_KEY.
    O modo escuro do aparelho e o valor antigo salvo automaticamente em
    THEME_KEY não são mais seguidos (deixavam a tela de entrada ilegível).
  */
  function loadTheme() {
    var choice =
      storageGet(
        THEME_CHOICE_KEY
      );

    state.theme =
      choice === "dark"
        ? "dark"
        : "light";

    return state.theme;
  }

  function applyTheme(theme) {
    var cleanTheme =
      normalizeTheme(
        theme
      );

    state.theme =
      cleanTheme;

    if (
      document &&
      document.documentElement
    ) {
      document.documentElement
        .setAttribute(
          "data-theme",
          cleanTheme
        );
    }

    storageSet(
      THEME_KEY,
      cleanTheme
    );

    return cleanTheme;
  }

  function toggleTheme() {
    var nextTheme =
      state.theme ===
      "dark"
        ? "light"
        : "dark";

    storageSet(
      THEME_CHOICE_KEY,
      nextTheme
    );

    return applyTheme(
      nextTheme
    );
  }

  /*
    ============================================================
    ESTADO GLOBAL
    ============================================================
  */

  function isInitialized() {
    return (
      state.initialized ===
      true
    );
  }

  function getState() {
    return {
      currentUser:
        getCurrentUser(),

      currentPropertyId:
        getCurrentPropertyId(),

      currentScreen:
        getCurrentScreen(),

      theme:
        normalizeTheme(
          state.theme
        ),

      initialized:
        state.initialized ===
        true,

      initializedAt:
        state.initializedAt,

      lastSessionLoadedAt:
        state.lastSessionLoadedAt
    };
  }

  /*
    ============================================================
    INICIALIZAÇÃO
    ============================================================
  */

  function init() {
    /*
      Inicialização idempotente.
    */
    if (
      state.initialized
    ) {
      return getState();
    }

    loadSession();

    loadCurrentScreen();

    var theme =
      loadTheme();

    applyTheme(
      theme
    );

    state.initialized =
      true;

    state.initializedAt =
      nowIso();

    return getState();
  }

  /*
    ============================================================
    API PÚBLICA
    ============================================================
  */

  window.AppState = {
    SESSION_KEY:
      SESSION_KEY,

    THEME_KEY:
      THEME_KEY,

    SCREEN_KEY:
      SCREEN_KEY,

    SESSION_VERSION:
      SESSION_VERSION,

    SESSION_MAX_AGE_DAYS:
      SESSION_MAX_AGE_DAYS,

    VALID_SCREENS:
      VALID_SCREENS.slice(),

    state:
      state,

    init:
      init,

    isInitialized:
      isInitialized,

    getState:
      getState,

    loadSession:
      loadSession,

    saveSession:
      saveSession,

    refreshSession:
      refreshSession,

    persistSession:
      persistSession,

    clearSession:
      clearSession,

    getCurrentUser:
      getCurrentUser,

    getCurrentPropertyId:
      getCurrentPropertyId,

    setCurrentPropertyId:
      setCurrentPropertyId,

    setCurrentScreen:
      setCurrentScreen,

    getCurrentScreen:
      getCurrentScreen,

    loadCurrentScreen:
      loadCurrentScreen,

    loadTheme:
      loadTheme,

    applyTheme:
      applyTheme,

    toggleTheme:
      toggleTheme,

    isValidScreen:
      isValidScreen
  };
})();

;

/* ===== js/auth/crypto.js ===== */
/* AquaGest Pro — PBKDF2-SHA-256 para credenciais. */
(function () {
  "use strict";

  var PBKDF2_ITERATIONS = 120000;
  var PBKDF2_BITS = 256;

  function getCrypto() { return window.crypto || null; }

  function hasSecureCrypto() {
    return !!(getCrypto() && getCrypto().subtle && typeof getCrypto().getRandomValues === "function" && window.TextEncoder);
  }

  function requireSecureCrypto() {
    if (!hasSecureCrypto()) {
      throw new Error("Este navegador precisa de HTTPS e suporte a Web Crypto para entrar ou criar uma conta.");
    }
    return true;
  }

  function bytesToBase64(bytes) {
    var binary = "";
    for (var i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }

  function bufferToBase64(buffer) { return bytesToBase64(new Uint8Array(buffer)); }

  function base64ToBytes(value) {
    var binary = atob(String(value || ""));
    var bytes = new Uint8Array(binary.length);
    for (var i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  function arrayBufferToHex(buffer) {
    var bytes = new Uint8Array(buffer);
    var hex = [];
    for (var i = 0; i < bytes.length; i += 1) hex.push(bytes[i].toString(16).padStart(2, "0"));
    return hex.join("");
  }

  function generateSalt() {
    requireSecureCrypto();
    var salt = new Uint8Array(16);
    getCrypto().getRandomValues(salt);
    return bytesToBase64(salt);
  }

  async function sha256(text) {
    requireSecureCrypto();
    return arrayBufferToHex(await getCrypto().subtle.digest("SHA-256", new TextEncoder().encode(String(text || ""))));
  }

  async function derivePbkdf2(value, salt, iterations) {
    requireSecureCrypto();
    var key = await getCrypto().subtle.importKey("raw", new TextEncoder().encode(String(value || "")), "PBKDF2", false, ["deriveBits"]);
    var bits = await getCrypto().subtle.deriveBits({
      name: "PBKDF2",
      salt: base64ToBytes(salt),
      iterations: Number(iterations) || PBKDF2_ITERATIONS,
      hash: "SHA-256"
    }, key, PBKDF2_BITS);
    return bufferToBase64(bits);
  }

  async function hashValue(value) {
    var salt = generateSalt();
    return {
      algorithm: "PBKDF2-SHA-256",
      iterations: PBKDF2_ITERATIONS,
      salt: salt,
      hash: await derivePbkdf2(String(value || ""), salt, PBKDF2_ITERATIONS)
    };
  }

  async function verifyValue(value, storedHash) {
    requireSecureCrypto();
    if (!storedHash || !storedHash.salt || !storedHash.hash) return false;
    if (storedHash.algorithm === "PBKDF2-SHA-256") {
      return await derivePbkdf2(String(value || ""), storedHash.salt, storedHash.iterations) === storedHash.hash;
    }
    if (storedHash.algorithm === "SHA-256") {
      return await sha256(String(value || "") + ":" + storedHash.salt) === storedHash.hash;
    }
    return false;
  }

  window.AquaGestCrypto = {
    PBKDF2_ITERATIONS: PBKDF2_ITERATIONS,
    hasSecureCrypto: hasSecureCrypto,
    requireSecureCrypto: requireSecureCrypto,
    generateSalt: generateSalt,
    sha256: sha256,
    hashValue: hashValue,
    verifyValue: verifyValue,
    hashPassword: function (password) { return hashValue(password); },
    verifyPassword: function (password, hash) { return verifyValue(password, hash); },
    hashSecurityAnswer: function (answer) { return hashValue(String(answer || "").trim().toLowerCase()); },
    verifySecurityAnswer: function (answer, hash) { return verifyValue(String(answer || "").trim().toLowerCase(), hash); },
    needsUpgrade: function (storedHash) { return !storedHash || storedHash.algorithm !== "PBKDF2-SHA-256"; }
  };
})();

;

/* ===== js/auth/permissions.js ===== */
// @ts-nocheck

/*
  AquaGest Pro
  Arquivo: js/auth/permissions.js
  Etapa: segurança e autorização
  Versão: permissions-v4-desempenho-integrado
  Status:
  - Desempenho reconhecido oficialmente
  - telas produtivas protegidas por Piscicultura
  - registros isolados por propertyId
  - stores globais e produtivas separadas
  - diagnósticos TypeScript 7044 eliminados
  - compatibilidade com AppState e AuthService preservada
*/

(function () {
  "use strict";

  /*
    ============================================================
    TELAS
    ============================================================
  */

  var PRODUCTIVE_SCREENS = [
    "viveiros",
    "producao",
    "biometria",
    "previsoes",
    "sanidade",
    "desempenho",
    "agua",
    "arracoamento",
    "estoque",
    "financeiro",
    "relatorios"
  ];

  var FREE_SCREENS_WITHOUT_PROPERTY = [
    "dashboard",
    "piscicultura",
    "configuracoes",
    /* Calculadora de aeração: funciona sem piscicultura cadastrada (área digitada). */
    "dimensionamento"
  ];

  var PUBLIC_SCREENS = [
    "login",
    "criar-conta",
    "recuperar-senha"
  ];

  /*
    ============================================================
    STORES
    ============================================================
  */

  var PROPERTY_SCOPED_STORES = [
    "ponds",
    "production_cycles",
    "stockings",
    "biometries",
    "water_quality",
    "feeding_records",
    "mortality_records",
    "health_records",
    "inventory",
    "inventory_movements",
    "suppliers",
    "customers",
    "purchases",
    "sales",
    "financial_accounts",
    "financial_transactions",
    "financial_records",
    "alerts",
    "recommendations",
    "reports",
    "settings",
    "sync_queue",
    "backups",
    "audit_logs",
    "property_custom_parameters"
  ];

  var GLOBAL_STORES = [
    "users",
    "properties",
    "species",
    "technical_parameters",
    "species_technical_parameters",
    "schema_migrations",
    "app_versions"
  ];

  /*
    ============================================================
    NORMALIZAÇÃO
    ============================================================
  */

  function normalizeText(value) {
    if (
      value === null ||
      value === undefined
    ) {
      return "";
    }

    return String(value).trim();
  }

  function normalizeScreenName(value) {
    return normalizeText(value)
      .toLowerCase();
  }

  function normalizeStoreName(value) {
    return normalizeText(value)
      .toLowerCase();
  }

  function normalizeRole(value) {
    return normalizeText(value)
      .toLowerCase();
  }

  function normalizeStatus(value) {
    return normalizeText(value)
      .toLowerCase();
  }

  function sameId(first, second) {
    var a =
      normalizeText(first);

    var b =
      normalizeText(second);

    if (
      !a ||
      !b
    ) {
      return false;
    }

    return a === b;
  }

  /*
    ============================================================
    CONTEXTO ATUAL
    ============================================================
  */

  function getCurrentUser() {
    if (
      !window.AppState ||
      typeof window.AppState
        .getCurrentUser !==
        "function"
    ) {
      return null;
    }

    try {
      return (
        window.AppState
          .getCurrentUser() ||
        null
      );
    } catch (error) {
      return null;
    }
  }

  function getCurrentPropertyId() {
    if (
      !window.AppState ||
      typeof window.AppState
        .getCurrentPropertyId !==
        "function"
    ) {
      return null;
    }

    try {
      return (
        window.AppState
          .getCurrentPropertyId() ||
        null
      );
    } catch (error) {
      return null;
    }
  }

  /*
    ============================================================
    AUTENTICAÇÃO
    ============================================================
  */

  function isAuthenticated() {
    var user =
      getCurrentUser();

    if (!user) {
      return false;
    }

    return !!(
      normalizeText(
        user.id
      ) &&
      normalizeStatus(
        user.status
      ) === "active"
    );
  }

  function hasProperty() {
    return !!normalizeText(
      getCurrentPropertyId()
    );
  }

  function getUserRole() {
    var user =
      getCurrentUser();

    if (
      !user ||
      !user.role
    ) {
      return null;
    }

    return normalizeRole(
      user.role
    );
  }

  function isOwner() {
    return (
      getUserRole() ===
      "owner"
    );
  }

  /*
    ============================================================
    CLASSIFICAÇÃO DE TELAS
    ============================================================
  */

  function isPublicScreen(screenName) {
    var screen =
      normalizeScreenName(
        screenName
      );

    return (
      PUBLIC_SCREENS.indexOf(
        screen
      ) !== -1
    );
  }

  function isProductiveScreen(screenName) {
    var screen =
      normalizeScreenName(
        screenName
      );

    return (
      PRODUCTIVE_SCREENS.indexOf(
        screen
      ) !== -1
    );
  }

  function isFreeScreenWithoutProperty(
    screenName
  ) {
    var screen =
      normalizeScreenName(
        screenName
      );

    return (
      FREE_SCREENS_WITHOUT_PROPERTY
        .indexOf(
          screen
        ) !== -1
    );
  }

  function isKnownScreen(screenName) {
    var screen =
      normalizeScreenName(
        screenName
      );

    if (!screen) {
      return false;
    }

    return !!(
      isPublicScreen(screen) ||
      isProductiveScreen(screen) ||
      isFreeScreenWithoutProperty(
        screen
      )
    );
  }

  /*
    ============================================================
    PERMISSÃO DE TELAS
    ============================================================
  */

  function canAccessScreen(screenName) {
    var screen =
      normalizeScreenName(
        screenName
      );

    if (!screen) {
      return {
        allowed: false,
        reason: "Tela inválida.",
        screen: null
      };
    }

    if (
      !isKnownScreen(
        screen
      )
    ) {
      return {
        allowed: false,
        reason: "Tela não reconhecida.",
        screen: screen
      };
    }

    /*
      Telas públicas não exigem login.
    */
    if (
      isPublicScreen(
        screen
      )
    ) {
      return {
        allowed: true,
        reason: "Tela pública.",
        screen: screen
      };
    }

    /*
      Área interna exige autenticação.
    */
    if (
      !isAuthenticated()
    ) {
      return {
        allowed: false,
        reason:
          "Faça login para continuar.",
        screen: screen
      };
    }

    /*
      Regra atual do AquaGest Pro:
      proprietário possui acesso administrativo.
    */
    if (
      !isOwner()
    ) {
      return {
        allowed: false,
        reason:
          "Perfil de usuário sem permissão para acessar esta área.",
        screen: screen
      };
    }

    /*
      Painel, Piscicultura e Configurações
      podem ser abertas antes do cadastro
      da Piscicultura.
    */
    if (
      isFreeScreenWithoutProperty(
        screen
      )
    ) {
      return {
        allowed: true,
        reason: "Tela permitida.",
        screen: screen
      };
    }

    /*
      Todos os módulos produtivos precisam
      de uma Piscicultura atual.
    */
    if (
      isProductiveScreen(
        screen
      ) &&
      !hasProperty()
    ) {
      return {
        allowed: false,
        reason:
          "Cadastre sua piscicultura antes de acessar os módulos produtivos.",
        screen: screen
      };
    }

    return {
      allowed: true,
      reason: "Acesso permitido.",
      screen: screen
    };
  }

  /*
    ============================================================
    REQUIRE
    ============================================================
  */

  function requireLogin() {
    if (
      !isAuthenticated()
    ) {
      throw new Error(
        "Faça login para continuar."
      );
    }

    var user =
      getCurrentUser();

    if (!user) {
      throw new Error(
        "Sessão de usuário indisponível."
      );
    }

    return user;
  }

  function requireOwner() {
    var user =
      requireLogin();

    if (
      normalizeRole(
        user.role
      ) !== "owner"
    ) {
      throw new Error(
        "Apenas o proprietário pode executar esta ação."
      );
    }

    return user;
  }

  function requireProperty() {
    requireLogin();

    var propertyId =
      normalizeText(
        getCurrentPropertyId()
      );

    if (!propertyId) {
      throw new Error(
        "Cadastre sua piscicultura antes de continuar."
      );
    }

    return propertyId;
  }

  /*
    ============================================================
    CLASSIFICAÇÃO DE STORES
    ============================================================
  */

  function isPropertyScopedStore(
    storeName
  ) {
    var store =
      normalizeStoreName(
        storeName
      );

    return (
      PROPERTY_SCOPED_STORES
        .indexOf(
          store
        ) !== -1
    );
  }

  function isGlobalStore(
    storeName
  ) {
    var store =
      normalizeStoreName(
        storeName
      );

    return (
      GLOBAL_STORES.indexOf(
        store
      ) !== -1
    );
  }

  function isKnownStore(
    storeName
  ) {
    var store =
      normalizeStoreName(
        storeName
      );

    return !!(
      isPropertyScopedStore(
        store
      ) ||
      isGlobalStore(
        store
      )
    );
  }

  /*
    ============================================================
    ACESSO A REGISTROS
    ============================================================
  */

  function canAccessRecord(
    record,
    options
  ) {
    var config =
      options || {};

    var storeName =
      normalizeStoreName(
        config.storeName
      );

    var allowGlobalRecord =
      config.allowGlobalRecord ===
      true;

    var propertyId =
      normalizeText(
        getCurrentPropertyId()
      );

    if (
      !record ||
      typeof record !== "object"
    ) {
      return false;
    }

    if (
      !isAuthenticated()
    ) {
      return false;
    }

    if (
      record.deleted === true ||
      normalizeStatus(
        record.status
      ) === "deleted"
    ) {
      return false;
    }

    /*
      Stores globais não dependem de propertyId.
    */
    if (
      storeName &&
      isGlobalStore(
        storeName
      )
    ) {
      return true;
    }

    /*
      Uso explícito de registros globais
      quando autorizado pelo chamador.
    */
    if (
      allowGlobalRecord &&
      !normalizeText(
        record.propertyId
      )
    ) {
      return true;
    }

    /*
      Store produtiva precisa obrigatoriamente
      possuir propertyId.
    */
    if (
      storeName &&
      isPropertyScopedStore(
        storeName
      ) &&
      !normalizeText(
        record.propertyId
      )
    ) {
      return false;
    }

    /*
      Se existe propertyId no registro,
      ele precisa ser da Piscicultura atual.
    */
    if (
      normalizeText(
        record.propertyId
      )
    ) {
      return sameId(
        record.propertyId,
        propertyId
      );
    }

    return false;
  }

  function assertCanAccessRecord(
    record,
    options
  ) {
    if (
      !canAccessRecord(
        record,
        options
      )
    ) {
      throw new Error(
        "Acesso negado. Este registro não pertence à piscicultura atual."
      );
    }

    return true;
  }

  function assertCanCreatePropertyRecord(
    record
  ) {
    var propertyId =
      requireProperty();

    if (
      !record ||
      typeof record !== "object"
    ) {
      throw new Error(
        "Registro inválido."
      );
    }

    var recordPropertyId =
      normalizeText(
        record.propertyId
      );

    if (
      !recordPropertyId
    ) {
      throw new Error(
        "Registro sem propertyId."
      );
    }

    if (
      !sameId(
        recordPropertyId,
        propertyId
      )
    ) {
      throw new Error(
        "O propertyId do registro não confere com a piscicultura atual."
      );
    }

    return true;
  }

  /*
    ============================================================
    PERMISSÃO DE STORE
    ============================================================
  */

  function assertCanUseStore(
    storeName
  ) {
    var store =
      normalizeStoreName(
        storeName
      );

    if (!store) {
      throw new Error(
        "Store inválida."
      );
    }

    requireLogin();

    /*
      Stores vinculadas à Piscicultura
      exigem Piscicultura atual.
    */
    if (
      isPropertyScopedStore(
        store
      )
    ) {
      requireProperty();
      return true;
    }

    /*
      Stores globais são permitidas
      para usuário autenticado.
    */
    if (
      isGlobalStore(
        store
      )
    ) {
      return true;
    }

    /*
      Evita acesso silencioso a store
      desconhecida por erro de programação.
    */
    throw new Error(
      "Store não reconhecida pelo sistema de permissões: " +
      store
    );
  }

  /*
    ============================================================
    MENSAGENS
    ============================================================
  */

  function getBlockedMessage() {
    return (
      "Cadastre sua piscicultura antes de acessar os módulos produtivos."
    );
  }

  /*
    ============================================================
    API PÚBLICA
    ============================================================
  */

  window.AquaGestPermissions = {
    /*
      Cópias impedem alteração acidental
      das listas internas.
    */

    PRODUCTIVE_SCREENS:
      PRODUCTIVE_SCREENS.slice(),

    FREE_SCREENS_WITHOUT_PROPERTY:
      FREE_SCREENS_WITHOUT_PROPERTY.slice(),

    PUBLIC_SCREENS:
      PUBLIC_SCREENS.slice(),

    PROPERTY_SCOPED_STORES:
      PROPERTY_SCOPED_STORES.slice(),

    GLOBAL_STORES:
      GLOBAL_STORES.slice(),

    getCurrentUser:
      getCurrentUser,

    getCurrentPropertyId:
      getCurrentPropertyId,

    getUserRole:
      getUserRole,

    isAuthenticated:
      isAuthenticated,

    hasProperty:
      hasProperty,

    isOwner:
      isOwner,

    isPublicScreen:
      isPublicScreen,

    isProductiveScreen:
      isProductiveScreen,

    isFreeScreenWithoutProperty:
      isFreeScreenWithoutProperty,

    isKnownScreen:
      isKnownScreen,

    canAccessScreen:
      canAccessScreen,

    requireLogin:
      requireLogin,

    requireOwner:
      requireOwner,

    requireProperty:
      requireProperty,

    isPropertyScopedStore:
      isPropertyScopedStore,

    isGlobalStore:
      isGlobalStore,

    isKnownStore:
      isKnownStore,

    canAccessRecord:
      canAccessRecord,

    assertCanAccessRecord:
      assertCanAccessRecord,

    assertCanCreatePropertyRecord:
      assertCanCreatePropertyRecord,

    assertCanUseStore:
      assertCanUseStore,

    getBlockedMessage:
      getBlockedMessage
  };
})();

;

/* ===== js/auth/auth.js ===== */
