(function () {
  "use strict";

  var STORE_NAME = "properties";
  var PROPERTY_CHANGED_EVENT = "aquagest:property-changed";

  var VALID_STRUCTURE_TYPES_FOR_PONDS = [
    "Viveiro escavado",
    "Tanque-rede",
    "Geomembrana"
  ];

  function ensureDependencies() {
    if (!window.database) {
      throw new Error("Banco local não carregado.");
    }

    if (!window.AuthService) {
      throw new Error("Serviço de autenticação não carregado.");
    }
  }

  function normalizeText(value) {
    return String(value === null || value === undefined ? "" : value).trim();
  }

  function normalizeLower(value) {
    return normalizeText(value).toLowerCase();
  }

  function normalizeEmail(value) {
    return normalizeLower(value);
  }

  function normalizeState(value) {
    return normalizeText(value).toUpperCase();
  }

  function normalizeStatus(value) {
    var status = normalizeLower(value);

    if (status === "inactive" || status === "inativo") return "inactive";
    if (status === "deleted" || status === "excluido" || status === "excluído") return "deleted";

    return "active";
  }

  function nowIso() {
    return new Date().toISOString();
  }

  function hasOwn(object, key) {
    return Object.prototype.hasOwnProperty.call(object || {}, key);
  }

  function firstValue(data, aliases, fallback) {
    var input = data || {};

    for (var i = 0; i < aliases.length; i += 1) {
      var key = aliases[i];

      if (hasOwn(input, key)) {
        return input[key];
      }
    }

    return fallback;
  }

  function parseLocalizedNumber(value) {
    if (value === null || value === undefined || value === "") {
      return null;
    }

    if (typeof value === "number") {
      return Number.isFinite(value) ? value : null;
    }

    var text = String(value).trim();

    if (!text) {
      return null;
    }

    text = text.replace(/\s/g, "");

    if (text.indexOf(",") >= 0 && text.indexOf(".") >= 0) {
      text = text.replace(/\./g, "").replace(",", ".");
    } else if (text.indexOf(",") >= 0) {
      text = text.replace(",", ".");
    }

    var number = Number(text);

    if (!Number.isFinite(number)) {
      return null;
    }

    return number;
  }

  function round(value, decimals) {
    var number = Number(value);

    if (!Number.isFinite(number)) {
      return 0;
    }

    var factor = Math.pow(10, decimals || 2);
    return Math.round(number * factor) / factor;
  }

  function getCurrentUser() {
    ensureDependencies();

    if (typeof window.AuthService.requireLogin === "function") {
      return window.AuthService.requireLogin();
    }

    if (typeof window.AuthService.getCurrentUser === "function") {
      var user = window.AuthService.getCurrentUser();

      if (user) {
        return user;
      }
    }

    throw new Error("Faça login para acessar os dados da piscicultura.");
  }

  function getCurrentPropertyId() {
    ensureDependencies();

    if (typeof window.AuthService.getCurrentPropertyId === "function") {
      return window.AuthService.getCurrentPropertyId();
    }

    var user = null;

    if (typeof window.AuthService.getCurrentUser === "function") {
      user = window.AuthService.getCurrentUser();
    }

    return user && user.propertyId ? user.propertyId : null;
  }

  function isUsableProperty(property) {
    return !!(
      property &&
      property.id &&
      property.deleted !== true &&
      property.status !== "deleted"
    );
  }

  function isPropertyId(value) {
    return /^property_/i.test(normalizeText(value));
  }

  function generateSafePropertyId() {
    if (
      window.AquaGestId &&
      typeof window.AquaGestId.generatePropertyId === "function"
    ) {
      return window.AquaGestId.generatePropertyId();
    }

    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return "property_" + window.crypto.randomUUID();
    }

    return "property_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10);
  }

  function formatPropertyCode(propertyId) {
    var rawId = normalizeText(propertyId);

    if (!rawId) {
      return "";
    }

    var cleaned = rawId
      .replace(/^property_/i, "")
      .replace(/[^a-zA-Z0-9]/g, "")
      .toUpperCase();

    if (!cleaned) {
      return "";
    }

    return "AGP-" + cleaned.slice(0, 8);
  }

  function normalizeProductionType(value) {
    var text = normalizeText(value);

    if (!text) {
      return "Tilápia";
    }

    var lower = normalizeLower(text);

    if (lower === "tilapia") {
      return "Tilápia";
    }

    return text;
  }

  function normalizeSystemType(value) {
    var text = normalizeText(value);

    if (!text) {
      return "";
    }

    var lower = normalizeLower(text)
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");

    if (
      lower === "viveiro escavado" ||
      lower === "viveiros escavados" ||
      lower === "escavado" ||
      lower === "tanque escavado"
    ) {
      return "Viveiro escavado";
    }

    if (
      lower === "tanque-rede" ||
      lower === "tanque rede" ||
      lower === "tanques-rede" ||
      lower === "tanques rede"
    ) {
      return "Tanque-rede";
    }

    if (
      lower === "geomembrana" ||
      lower === "tanque de geomembrana" ||
      lower === "tanques de geomembrana"
    ) {
      return "Geomembrana";
    }

    return text;
  }

  function getSuggestedPondStructureType(systemTypeOrProperty) {
    var systemType = "";

    if (typeof systemTypeOrProperty === "object" && systemTypeOrProperty) {
      systemType = systemTypeOrProperty.systemType || "";
    } else {
      systemType = systemTypeOrProperty || "";
    }

    var normalized = normalizeSystemType(systemType);

    if (VALID_STRUCTURE_TYPES_FOR_PONDS.indexOf(normalized) >= 0) {
      return normalized;
    }

    return "";
  }

  async function dbGet(storeName, id) {
    ensureDependencies();

    if (!id) {
      return null;
    }

    if (typeof window.database.get === "function") {
      return window.database.get(storeName, id);
    }

    if (typeof window.database.getById === "function") {
      return window.database.getById(storeName, id);
    }

    throw new Error("Método de busca do banco local não encontrado.");
  }

  async function dbGetAll(storeName) {
    ensureDependencies();

    if (typeof window.database.getAll === "function") {
      return window.database.getAll(storeName);
    }

    if (typeof window.database.all === "function") {
      return window.database.all(storeName);
    }

    throw new Error("Método de listagem do banco local não encontrado.");
  }

  async function dbAdd(storeName, record) {
    ensureDependencies();

    if (typeof window.database.add === "function") {
      return window.database.add(storeName, record);
    }

    if (typeof window.database.create === "function") {
      return window.database.create(storeName, record);
    }

    if (typeof window.database.put === "function") {
      return window.database.put(storeName, record);
    }

    if (typeof window.database.save === "function") {
      return window.database.save(storeName, record);
    }

    throw new Error("Método de gravação do banco local não encontrado.");
  }

  async function dbPut(storeName, record) {
    ensureDependencies();

    if (typeof window.database.put === "function") {
      return window.database.put(storeName, record);
    }

    if (typeof window.database.update === "function") {
      return window.database.update(storeName, record);
    }

    if (typeof window.database.save === "function") {
      return window.database.save(storeName, record);
    }

    throw new Error("Método de atualização do banco local não encontrado.");
  }

  function propertyBelongsToUser(property, user) {
    if (!property || !user) {
      return false;
    }

    if (property.createdBy && property.createdBy !== user.id) {
      return false;
    }

    if (property.ownerUserId && property.ownerUserId !== user.id) {
      return false;
    }

    if (property.userId && property.userId !== user.id) {
      return false;
    }

    return true;
  }

  function propertyMatchesUser(property, user) {
    if (!property || !user) {
      return false;
    }

    if (property.createdBy === user.id) return true;
    if (property.ownerUserId === user.id) return true;
    if (property.userId === user.id) return true;
    if (user.propertyId && property.id === user.propertyId) return true;

    if (
      user.email &&
      property.email &&
      normalizeEmail(user.email) === normalizeEmail(property.email)
    ) {
      return true;
    }

    return false;
  }

  function validateRequiredFields(data) {
    var input = data || {};

    var name = normalizeText(firstValue(input, [
      "name",
      "property_name",
      "pisciculturaName",
      "piscicultura_nome",
      "nomePiscicultura"
    ], ""));

    var ownerName = normalizeText(firstValue(input, [
      "ownerName",
      "owner_name",
      "property_ownerName",
      "responsibleName",
      "responsavel",
      "responsavelTecnico",
      "nomeResponsavel"
    ], ""));

    var city = normalizeText(firstValue(input, [
      "city",
      "property_city",
      "municipio",
      "municipality",
      "cidade"
    ], ""));

    var state = normalizeState(firstValue(input, [
      "state",
      "property_state",
      "uf",
      "estado"
    ], ""));

    if (!name) {
      throw new Error("Informe o nome da piscicultura.");
    }

    if (!ownerName) {
      throw new Error("Informe o responsável técnico/proprietário.");
    }

    if (!city) {
      throw new Error("Informe o município.");
    }

    if (!state) {
      throw new Error("Informe a UF.");
    }

    if (state.length !== 2) {
      throw new Error("Informe a UF com 2 letras. Exemplo: PR, SP, MS.");
    }

    return {
      name: name,
      ownerName: ownerName,
      city: city,
      state: state
    };
  }

  function normalizePropertyInput(data, user) {
    var input = data || {};
    var currentUser = user || getCurrentUser();
    var required = validateRequiredFields(input);

    var area = parseLocalizedNumber(firstValue(input, [
      "area",
      "property_area",
      "totalArea",
      "areaTotal"
    ], null));

    return {
      name: required.name,
      ownerName: required.ownerName,

      document: normalizeText(firstValue(input, [
        "document",
        "property_document",
        "cpfCnpj",
        "cpf_cnpj",
        "cnpj",
        "documento"
      ], "")),

      email: normalizeEmail(firstValue(input, [
        "email",
        "property_email",
        "contatoEmail"
      ], currentUser.email || "")),

      phone: normalizeText(firstValue(input, [
        "phone",
        "property_phone",
        "telefone",
        "celular",
        "whatsapp"
      ], "")),

      city: required.city,
      state: required.state,

      address: normalizeText(firstValue(input, [
        "address",
        "property_address",
        "endereco",
        "localizacao"
      ], "")),

      area: area === null ? null : round(area, 4),

      areaUnit: normalizeText(firstValue(input, [
        "areaUnit",
        "property_areaUnit",
        "unidadeArea"
      ], "ha")) || "ha",

      productionType: normalizeProductionType(firstValue(input, [
        "productionType",
        "property_productionType",
        "tipoProducao",
        "atividadeProdutiva",
        "especiePrincipal"
      ], "Tilápia")),

      systemType: normalizeSystemType(firstValue(input, [
        "systemType",
        "property_systemType",
        "sistemaCultivo",
        "cultivationSystem",
        "tipoSistema"
      ], "")),

      notes: normalizeText(firstValue(input, [
        "notes",
        "property_notes",
        "observations",
        "observacoes",
        "observacoesTecnicas"
      ], "")),

      status: normalizeStatus(firstValue(input, [
        "status",
        "property_status"
      ], "active")),

      deleted: false
    };
  }

  function createPropertyEntity(payload, user) {
    var now = nowIso();
    var property = null;

    if (
      window.AquaGestModels &&
      typeof window.AquaGestModels.createProperty === "function"
    ) {
      property = window.AquaGestModels.createProperty(payload);
    } else {
      property = Object.assign({}, payload, {
        id: generateSafePropertyId(),
        createdAt: now,
        updatedAt: now,
        version: 1
      });
    }

    property.id = property.id || generateSafePropertyId();
    property.createdBy = user.id;
    property.updatedBy = user.id;
    property.createdAt = property.createdAt || now;
    property.updatedAt = property.updatedAt || property.createdAt;
    property.version = Number(property.version) || 1;
    property.status = "active";
    property.deleted = false;

    return property;
  }

  function prepareUpdatedProperty(existing, payload, user) {
    var now = nowIso();
    var updated = null;

    if (
      window.AquaGestModels &&
      typeof window.AquaGestModels.prepareForUpdate === "function"
    ) {
      updated = window.AquaGestModels.prepareForUpdate(existing, payload);
    } else {
      updated = Object.assign({}, existing, payload);
    }

    updated.id = existing.id;
    updated.createdBy = existing.createdBy || user.id;
    updated.updatedBy = user.id;
    updated.createdAt = existing.createdAt || now;
    updated.updatedAt = now;
    updated.version = (Number(existing.version) || 1) + 1;
    updated.status = payload.status || existing.status || "active";
    updated.deleted = false;

    return updated;
  }

  async function updateSessionPropertyId(propertyId) {
    if (!propertyId) {
      return;
    }

    if (
      window.AuthService &&
      typeof window.AuthService.updateCurrentUserProperty === "function"
    ) {
      await window.AuthService.updateCurrentUserProperty(propertyId);
      return;
    }

    if (
      window.AppState &&
      typeof window.AppState.setCurrentPropertyId === "function"
    ) {
      window.AppState.setCurrentPropertyId(propertyId);
    }
  }

  async function safeAuditLog(action, property, user) {
    try {
      if (!window.database || typeof window.database.add !== "function") {
        return;
      }

      var record = {
        id: "audit_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10),
        propertyId: property && property.id ? property.id : null,
        action: action,
        entity: "properties",
        entityId: property && property.id ? property.id : null,
        createdBy: user && user.id ? user.id : null,
        createdAt: nowIso(),
        status: "active",
        deleted: false
      };

      await window.database.add("audit_logs", record);
    } catch (error) {
      return;
    }
  }

  function emitPropertyChanged(property, action) {
    try {
      var detail = {
        action: action || "updated",
        property: property || null,
        summary: formatPropertySummary(property || null)
      };

      window.dispatchEvent(new CustomEvent(PROPERTY_CHANGED_EVENT, {
        detail: detail
      }));
    } catch (error) {
      return;
    }

    if (
      window.AquaGestApp &&
      typeof window.AquaGestApp.notifyPropertyChanged === "function"
    ) {
      setTimeout(function () {
        try {
          window.AquaGestApp.notifyPropertyChanged();
        } catch (error) {
          return;
        }
      }, 0);
    }
  }

  async function getAllProperties() {
    var properties = await dbGetAll(STORE_NAME);

    if (!Array.isArray(properties)) {
      return [];
    }

    return properties;
  }

  async function findPropertyByUser(user) {
    var properties = await getAllProperties();

    var matches = properties.filter(function (property) {
      return isUsableProperty(property) && propertyMatchesUser(property, user);
    });

    matches.sort(function (a, b) {
      return String(b.updatedAt || b.createdAt || "").localeCompare(String(a.updatedAt || a.createdAt || ""));
    });

    return matches[0] || null;
  }

  async function getPropertyById(propertyId) {
    ensureDependencies();

    var user = getCurrentUser();
    var id = normalizeText(propertyId);

    if (!id) {
      return null;
    }

    var property = await dbGet(STORE_NAME, id);

    if (!isUsableProperty(property)) {
      return null;
    }

    if (!propertyBelongsToUser(property, user)) {
      throw new Error("Esta piscicultura não pertence ao usuário atual.");
    }

    return property;
  }

  async function getCurrentProperty() {
    ensureDependencies();

    var user = getCurrentUser();
    var propertyId = getCurrentPropertyId();

    if (propertyId) {
      var property = await dbGet(STORE_NAME, propertyId);

      if (isUsableProperty(property)) {
        if (!propertyBelongsToUser(property, user)) {
          throw new Error("Esta piscicultura não pertence ao usuário atual.");
        }

        await updateSessionPropertyId(property.id);
        return property;
      }
    }

    var recoveredProperty = await findPropertyByUser(user);

    if (recoveredProperty) {
      await updateSessionPropertyId(recoveredProperty.id);
      return recoveredProperty;
    }

    return null;
  }

  async function assertCurrentProperty() {
    var property = await getCurrentProperty();

    if (!property) {
      throw new Error("Cadastre sua piscicultura para acessar os módulos produtivos.");
    }

    return property;
  }

  async function createProperty(data) {
    ensureDependencies();

    var user = getCurrentUser();
    var existingProperty = await getCurrentProperty();

    if (existingProperty) {
      throw new Error("Este usuário já possui uma piscicultura cadastrada.");
    }

    var payload = normalizePropertyInput(data, user);
    var property = createPropertyEntity(payload, user);

    var currentPropertyId = getCurrentPropertyId();

    if (currentPropertyId && isPropertyId(currentPropertyId)) {
      var storedWithCurrentId = await dbGet(STORE_NAME, currentPropertyId);

      if (!storedWithCurrentId) {
        property.id = currentPropertyId;
      }
    }

    var idAlreadyUsed = await dbGet(STORE_NAME, property.id);

    if (idAlreadyUsed) {
      property.id = generateSafePropertyId();
    }

    await dbAdd(STORE_NAME, property);
    await updateSessionPropertyId(property.id);
    await safeAuditLog("create_property", property, user);

    emitPropertyChanged(property, "created");

    return property;
  }

  async function updateProperty(data) {
    ensureDependencies();

    var user = getCurrentUser();
    var existing = await getCurrentProperty();

    if (!existing) {
      throw new Error("Nenhuma piscicultura cadastrada para atualizar.");
    }

    if (!propertyBelongsToUser(existing, user)) {
      throw new Error("Esta piscicultura não pertence ao usuário atual.");
    }

    var payload = normalizePropertyInput(data, user);
    var updated = prepareUpdatedProperty(existing, payload, user);

    await dbPut(STORE_NAME, updated);
    await updateSessionPropertyId(updated.id);
    await safeAuditLog("update_property", updated, user);

    emitPropertyChanged(updated, "updated");

    return updated;
  }

  async function saveProperty(data) {
    ensureDependencies();

    var current = await getCurrentProperty();

    if (current) {
      return updateProperty(data);
    }

    return createProperty(data);
  }

  async function refreshCurrentPropertySession() {
    var property = await getCurrentProperty();

    if (property) {
      await updateSessionPropertyId(property.id);
    }

    return property;
  }

  async function hasCurrentProperty() {
    var property = await getCurrentProperty();
    return !!property;
  }

  async function getPropertyContext() {
    var property = await getCurrentProperty();
    var summary = formatPropertySummary(property);

    return {
      hasProperty: !!property,
      property: property,
      propertyId: property ? property.id : null,
      propertyCode: property ? formatPropertyCode(property.id) : null,
      suggestedPondStructureType: property ? getSuggestedPondStructureType(property) : "",
      summary: summary
    };
  }

  function formatPropertySummary(property) {
    if (!property) {
      return {
        hasProperty: false,
        title: "Piscicultura não cadastrada",
        description: "Registre sua piscicultura para liberar os módulos produtivos.",
        propertyId: null,
        propertyCode: null,
        propertyRawId: null,
        ownerName: "",
        productionType: "",
        systemType: "",
        suggestedPondStructureType: "",
        status: "",
        statusText: "Não cadastrada"
      };
    }

    var propertyCode = formatPropertyCode(property.id);
    var location = [
      property.city || "",
      property.state || ""
    ].filter(Boolean).join(" - ");

    return {
      hasProperty: true,
      title: property.name || "Piscicultura cadastrada",
      description: location,
      propertyId: propertyCode,
      propertyCode: propertyCode,
      propertyRawId: property.id,
      ownerName: property.ownerName || "",
      productionType: property.productionType || "",
      systemType: property.systemType || "",
      suggestedPondStructureType: getSuggestedPondStructureType(property),
      city: property.city || "",
      state: property.state || "",
      location: location,
      area: property.area === null || property.area === undefined ? null : property.area,
      areaUnit: property.areaUnit || "ha",
      status: property.status || "active",
      statusText: translateStatus(property.status || "active"),
      updatedAt: property.updatedAt || "",
      createdAt: property.createdAt || ""
    };
  }

  function formatPropertyForForm(property) {
    if (!property) {
      return {
        id: "",
        name: "",
        ownerName: "",
        document: "",
        email: "",
        phone: "",
        city: "",
        state: "",
        address: "",
        area: "",
        areaUnit: "ha",
        productionType: "Tilápia",
        systemType: "",
        notes: ""
      };
    }

    return {
      id: property.id || "",
      name: property.name || "",
      ownerName: property.ownerName || "",
      document: property.document || "",
      email: property.email || "",
      phone: property.phone || "",
      city: property.city || "",
      state: property.state || "",
      address: property.address || "",
      area: property.area === null || property.area === undefined ? "" : property.area,
      areaUnit: property.areaUnit || "ha",
      productionType: property.productionType || "Tilápia",
      systemType: property.systemType || "",
      notes: property.notes || ""
    };
  }

  function translateStatus(status) {
    var value = normalizeStatus(status);

    if (value === "active") return "Ativa";
    if (value === "inactive") return "Inativa";
    if (value === "deleted") return "Excluída";

    return "Não informada";
  }

  function canUseProductiveModules(property) {
    return !!isUsableProperty(property);
  }

  function getAllowedPondStructureTypes() {
    return VALID_STRUCTURE_TYPES_FOR_PONDS.slice();
  }

  window.PisciculturaService = {
    getCurrentProperty: getCurrentProperty,
    getPropertyById: getPropertyById,
    getAllProperties: getAllProperties,
    getPropertyContext: getPropertyContext,

    createProperty: createProperty,
    updateProperty: updateProperty,
    saveProperty: saveProperty,

    hasCurrentProperty: hasCurrentProperty,
    assertCurrentProperty: assertCurrentProperty,
    refreshCurrentPropertySession: refreshCurrentPropertySession,

    normalizePropertyInput: normalizePropertyInput,
    formatPropertySummary: formatPropertySummary,
    formatPropertyForForm: formatPropertyForForm,
    formatPropertyCode: formatPropertyCode,

    normalizeSystemType: normalizeSystemType,
    getSuggestedPondStructureType: getSuggestedPondStructureType,
    getAllowedPondStructureTypes: getAllowedPondStructureTypes,

    canUseProductiveModules: canUseProductiveModules,
    translateStatus: translateStatus
  };
})();
;

/* ===== js/ui/piscicultura-ui.js ===== */
/*
  AquaGest Pro
  Arquivo: js/ui/piscicultura-ui.js
  Etapa: 3/4 — Piscicultura
  Versão reconstruída: piscicultura-ui-core-v8
  Status: salvamento, máscaras, município→UF sem bagunçar layout e integração Piscicultura → Viveiros
*/

(function () {
  "use strict";

  var initialized = false;
  var currentPropertyCache = null;
  var loading = false;
  var saving = false;

  var PROPERTY_CHANGED_EVENT = "aquagest:property-changed";
  var MUNICIPALITIES_CACHE_KEY = "aquagest:brazil-municipalities:v2";

  var municipalitiesCache = null;
  var citySuggestionTimer = null;
  var lastAutoState = "";
  var stateManuallyEdited = false;

  var FALLBACK_MUNICIPALITIES = [
    { name: "Toledo", state: "PR" },
    { name: "Cascavel", state: "PR" },
    { name: "Palotina", state: "PR" },
    { name: "Marechal Cândido Rondon", state: "PR" },
    { name: "Foz do Iguaçu", state: "PR" },
    { name: "Medianeira", state: "PR" },
    { name: "Assis Chateaubriand", state: "PR" },
    { name: "Guaíra", state: "PR" },
    { name: "Santa Helena", state: "PR" },
    { name: "Curitiba", state: "PR" },
    { name: "Londrina", state: "PR" },
    { name: "Maringá", state: "PR" },
    { name: "São Paulo", state: "SP" },
    { name: "Campinas", state: "SP" },
    { name: "Ribeirão Preto", state: "SP" },
    { name: "Campo Grande", state: "MS" },
    { name: "Dourados", state: "MS" },
    { name: "Três Lagoas", state: "MS" },
    { name: "Cuiabá", state: "MT" },
    { name: "Sorriso", state: "MT" },
    { name: "Sinop", state: "MT" },
    { name: "Rondonópolis", state: "MT" },
    { name: "Florianópolis", state: "SC" },
    { name: "Joinville", state: "SC" },
    { name: "Chapecó", state: "SC" },
    { name: "Porto Alegre", state: "RS" },
    { name: "Belo Horizonte", state: "MG" },
    { name: "Uberlândia", state: "MG" },
    { name: "Goiânia", state: "GO" },
    { name: "Rio Verde", state: "GO" },
    { name: "Brasília", state: "DF" },
    { name: "Salvador", state: "BA" },
    { name: "Recife", state: "PE" },
    { name: "Fortaleza", state: "CE" },
    { name: "Manaus", state: "AM" },
    { name: "Belém", state: "PA" }
  ];

  function getElement(id) {
    return document.getElementById(id);
  }

  function normalizeText(value) {
    return String(value === null || value === undefined ? "" : value).trim();
  }

  function normalizeState(value) {
    return normalizeText(value).toUpperCase();
  }

  function normalizeSearch(value) {
    return normalizeText(value)
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");
  }

  function onlyDigits(value) {
    return String(value || "").replace(/\D/g, "");
  }

  function setText(id, value) {
    var element = getElement(id);

    if (element) {
      element.textContent = value;
    }
  }

  function setValue(id, value) {
    var element = getElement(id);

    if (!element) {
      return;
    }

    var finalValue = value === null || value === undefined ? "" : String(value);

    if (element.tagName === "SELECT" && finalValue) {
      ensureSelectOption(element, finalValue);
    }

    element.value = finalValue;
  }

  function ensureSelectOption(selectElement, value) {
    var exists = false;

    Array.prototype.forEach.call(selectElement.options || [], function (option) {
      if (option.value === value) {
        exists = true;
      }
    });

    if (!exists) {
      var option = document.createElement("option");
      option.value = value;
      option.textContent = value;
      selectElement.appendChild(option);
    }
  }

  function showElement(id) {
    var element = getElement(id);

    if (element) {
      element.classList.remove("hidden");
    }
  }

  function setDisabled(id, disabled) {
    var element = getElement(id);

    if (element) {
      element.disabled = !!disabled;
    }
  }

  function showMessage(message, type) {
    if (
      window.AquaGestApp &&
      typeof window.AquaGestApp.showMessage === "function"
    ) {
      window.AquaGestApp.showMessage(message, type || "success");
      return;
    }

    alert(message);
  }

  function getService() {
    return window.PisciculturaService || null;
  }

  function isUserLoggedIn() {
    if (
      !window.AuthService ||
      typeof window.AuthService.getCurrentUser !== "function"
    ) {
      return false;
    }

    try {
      return !!window.AuthService.getCurrentUser();
    } catch (error) {
      return false;
    }
  }

  async function ensureDatabaseReady() {
    if (
      window.database &&
      typeof window.database.init === "function"
    ) {
      await window.database.init();
    }
  }

  function applyCpfCnpjMask(value) {
    var digits = onlyDigits(value).slice(0, 14);

    if (digits.length <= 11) {
      digits = digits.replace(/^(\d{3})(\d)/, "$1.$2");
      digits = digits.replace(/^(\d{3})\.(\d{3})(\d)/, "$1.$2.$3");
      digits = digits.replace(/^(\d{3})\.(\d{3})\.(\d{3})(\d)/, "$1.$2.$3-$4");
      return digits;
    }

    digits = digits.replace(/^(\d{2})(\d)/, "$1.$2");
    digits = digits.replace(/^(\d{2})\.(\d{3})(\d)/, "$1.$2.$3");
    digits = digits.replace(/^(\d{2})\.(\d{3})\.(\d{3})(\d)/, "$1.$2.$3/$4");
    digits = digits.replace(/^(\d{2})\.(\d{3})\.(\d{3})\/(\d{4})(\d)/, "$1.$2.$3/$4-$5");
    return digits;
  }

  function applyPhoneMask(value) {
    var digits = onlyDigits(value).slice(0, 11);

    if (digits.length <= 10) {
      digits = digits.replace(/^(\d{2})(\d)/, "($1) $2");
      digits = digits.replace(/(\d{4})(\d)/, "$1-$2");
      return digits;
    }

    digits = digits.replace(/^(\d{2})(\d)/, "($1) $2");
    digits = digits.replace(/(\d{5})(\d)/, "$1-$2");
    return digits;
  }

  function bindMasks() {
    var documentInput = getElement("property_document");
    var phoneInput = getElement("property_phone");

    if (documentInput) {
      documentInput.setAttribute("inputmode", "numeric");
      documentInput.setAttribute("autocomplete", "off");

      documentInput.addEventListener("input", function () {
        documentInput.value = applyCpfCnpjMask(documentInput.value);
      });

      documentInput.addEventListener("blur", function () {
        documentInput.value = applyCpfCnpjMask(documentInput.value);
      });
    }

    if (phoneInput) {
      phoneInput.setAttribute("inputmode", "numeric");
      phoneInput.setAttribute("autocomplete", "tel");

      phoneInput.addEventListener("input", function () {
        phoneInput.value = applyPhoneMask(phoneInput.value);
      });

      phoneInput.addEventListener("blur", function () {
        phoneInput.value = applyPhoneMask(phoneInput.value);
      });
    }
  }

  function getUfFromMunicipalityApiItem(item) {
    if (
      item &&
      item.microrregiao &&
      item.microrregiao.mesorregiao &&
      item.microrregiao.mesorregiao.UF &&
      item.microrregiao.mesorregiao.UF.sigla
    ) {
      return item.microrregiao.mesorregiao.UF.sigla;
    }

    if (
      item &&
      item["regiao-imediata"] &&
      item["regiao-imediata"]["regiao-intermediaria"] &&
      item["regiao-imediata"]["regiao-intermediaria"].UF &&
      item["regiao-imediata"]["regiao-intermediaria"].UF.sigla
    ) {
      return item["regiao-imediata"]["regiao-intermediaria"].UF.sigla;
    }

    return "";
  }

  function readMunicipalitiesFromLocalStorage() {
    try {
      var raw = localStorage.getItem(MUNICIPALITIES_CACHE_KEY);

      if (!raw) {
        return null;
      }

      var parsed = JSON.parse(raw);

      if (!Array.isArray(parsed) || parsed.length < 100) {
        return null;
      }

      return parsed;
    } catch (error) {
      return null;
    }
  }

  function saveMunicipalitiesToLocalStorage(list) {
    try {
      if (Array.isArray(list) && list.length > 100) {
        localStorage.setItem(MUNICIPALITIES_CACHE_KEY, JSON.stringify(list));
      }
    } catch (error) {
      return;
    }
  }

  async function fetchMunicipalitiesOnline() {
    if (!navigator.onLine || typeof fetch !== "function") {
      return null;
    }

    try {
      var response = await fetch(
        "https://servicodados.ibge.gov.br/api/v1/localidades/municipios?orderBy=nome",
        { cache: "force-cache" }
      );

      if (!response || !response.ok) {
        return null;
      }

      var data = await response.json();

      if (!Array.isArray(data)) {
        return null;
      }

      var mapped = data
        .map(function (item) {
          return {
            name: normalizeText(item.nome),
            state: normalizeState(getUfFromMunicipalityApiItem(item))
          };
        })
        .filter(function (item) {
          return item.name && item.state && item.state.length === 2;
        });

      return mapped.length > 100 ? mapped : null;
    } catch (error) {
      return null;
    }
  }

  async function loadMunicipalities() {
    if (municipalitiesCache) {
      return municipalitiesCache;
    }

    var stored = readMunicipalitiesFromLocalStorage();

    if (stored) {
      municipalitiesCache = stored;
      return municipalitiesCache;
    }

    var online = await fetchMunicipalitiesOnline();

    if (online) {
      municipalitiesCache = online;
      saveMunicipalitiesToLocalStorage(online);
      return municipalitiesCache;
    }

    municipalitiesCache = FALLBACK_MUNICIPALITIES.slice();
    return municipalitiesCache;
  }

  function removeOldCityDatalist() {
    var cityInput = getElement("property_city");
    var oldDatalist = getElement("propertyCitySuggestions");

    if (cityInput) {
      cityInput.removeAttribute("list");
      cityInput.setAttribute("autocomplete", "address-level2");
    }

    if (oldDatalist && oldDatalist.parentNode) {
      oldDatalist.parentNode.removeChild(oldDatalist);
    }
  }

  function canAutoSetState() {
    var stateInput = getElement("property_state");
    var currentState = stateInput ? normalizeState(stateInput.value) : "";

    if (!currentState) {
      return true;
    }

    if (lastAutoState && currentState === lastAutoState) {
      return true;
    }

    return !stateManuallyEdited;
  }

  function setStateFromCity(state) {
    var stateInput = getElement("property_state");
    var normalized = normalizeState(state).slice(0, 2);

    if (!stateInput || !normalized) {
      return;
    }

    if (!canAutoSetState()) {
      return;
    }

    stateInput.value = normalized;
    lastAutoState = normalized;
    stateManuallyEdited = false;
  }

  async function suggestStateFromCity() {
    var cityInput = getElement("property_city");

    if (!cityInput) {
      return;
    }

    var typed = normalizeText(cityInput.value);

    if (!typed || typed.length < 3) {
      return;
    }

    var list = await loadMunicipalities();
    var search = normalizeSearch(typed);

    var exactMatches = list.filter(function (item) {
      return normalizeSearch(item.name) === search;
    });

    if (exactMatches.length === 1) {
      setStateFromCity(exactMatches[0].state);
      return;
    }

    var startsWithMatches = list.filter(function (item) {
      return normalizeSearch(item.name).indexOf(search) === 0;
    });

    if (startsWithMatches.length === 1 && typed.length >= 5) {
      setStateFromCity(startsWithMatches[0].state);
    }
  }

  function bindCityStateSuggestion() {
    var cityInput = getElement("property_city");
    var stateInput = getElement("property_state");

    removeOldCityDatalist();

    if (cityInput) {
      cityInput.addEventListener("input", function () {
        clearTimeout(citySuggestionTimer);

        citySuggestionTimer = setTimeout(function () {
          suggestStateFromCity();
        }, 450);
      });

      cityInput.addEventListener("blur", function () {
        suggestStateFromCity();
      });
    }

    if (stateInput) {
      stateInput.setAttribute("autocomplete", "address-level1");

      stateInput.addEventListener("input", function () {
        var normalized = normalizeState(stateInput.value).slice(0, 2);

        if (stateInput.value !== normalized) {
          stateInput.value = normalized;
        }

        if (normalized && normalized !== lastAutoState) {
          stateManuallyEdited = true;
        }
      });

      stateInput.addEventListener("blur", function () {
        stateInput.value = normalizeState(stateInput.value).slice(0, 2);
      });
    }

    setTimeout(function () {
      loadMunicipalities();
    }, 1200);
  }

  function readInputValue(id) {
    var element = getElement(id);
    return element ? normalizeText(element.value) : "";
  }

  function collectPropertyFormValues() {
    return {
      id: currentPropertyCache && currentPropertyCache.id ? currentPropertyCache.id : "",

      name: readInputValue("property_name"),
      ownerName: readInputValue("property_ownerName"),
      document: readInputValue("property_document"),
      email: readInputValue("property_email"),
      phone: readInputValue("property_phone"),
      city: readInputValue("property_city"),
      state: normalizeState(readInputValue("property_state")),
      address: readInputValue("property_address"),
      area: readInputValue("property_area"),
      areaUnit: readInputValue("property_areaUnit") || "ha",
      productionType: readInputValue("property_productionType") || "Tilápia",
      systemType: readInputValue("property_systemType"),
      notes: readInputValue("property_notes")
    };
  }

  function getSummary(property) {
    var service = getService();

    if (
      service &&
      typeof service.formatPropertySummary === "function"
    ) {
      return service.formatPropertySummary(property);
    }

    if (!property) {
      return {
        hasProperty: false,
        title: "Piscicultura não cadastrada",
        description: "Registre sua piscicultura para liberar os módulos produtivos.",
        propertyCode: "",
        propertyId: "",
        propertyRawId: "",
        ownerName: "",
        productionType: "",
        systemType: ""
      };
    }

    return {
      hasProperty: true,
      title: property.name || "Piscicultura cadastrada",
      description: [property.city || "", property.state || ""].filter(Boolean).join(" - "),
      propertyCode: property.id || "",
      propertyId: property.id || "",
      propertyRawId: property.id || "",
      ownerName: property.ownerName || "",
      productionType: property.productionType || "",
      systemType: property.systemType || ""
    };
  }

  function resolvePropertyCode(property, summary) {
    var service = getService();
    var code = "";

    if (summary) {
      code = summary.propertyCode || summary.propertyId || "";
    }

    if (!code && property && property.id) {
      code = property.id;
    }

    if (
      /^property_/i.test(code) &&
      service &&
      typeof service.formatPropertyCode === "function"
    ) {
      code = service.formatPropertyCode(code);
    }

    return code || "Código será gerado ao salvar";
  }

  function renderSummary(property) {
    var summary = getSummary(property);

    showElement("propertySummaryBox");

    setText("propertySummaryTitle", summary.title || "Piscicultura não cadastrada");
    setText("propertySummaryDescription", summary.description || "Preencha os dados da piscicultura.");
    setText("propertySummaryId", resolvePropertyCode(property, summary));
    setText("propertySummaryOwner", summary.ownerName || "Responsável não informado");
    setText("propertySummaryProduction", summary.productionType || "Produção não informada");
    setText("propertySummarySystem", summary.systemType || "Sistema de cultivo não informado");

    var box = getElement("propertySummaryBox");

    if (box) {
      box.setAttribute("data-has-property", summary.hasProperty ? "true" : "false");
      box.setAttribute("data-property-id", summary.propertyRawId || "");
    }
  }

  function getFormModel(property) {
    var service = getService();

    if (
      service &&
      typeof service.formatPropertyForForm === "function"
    ) {
      return service.formatPropertyForForm(property);
    }

    if (!property) {
      return {
        name: "",
        ownerName: "",
        document: "",
        email: "",
        phone: "",
        city: "",
        state: "",
        address: "",
        area: "",
        areaUnit: "ha",
        productionType: "Tilápia",
        systemType: "",
        notes: ""
      };
    }

    return {
      name: property.name || "",
      ownerName: property.ownerName || "",
      document: property.document || "",
      email: property.email || "",
      phone: property.phone || "",
      city: property.city || "",
      state: property.state || "",
      address: property.address || "",
      area: property.area === null || property.area === undefined ? "" : property.area,
      areaUnit: property.areaUnit || "ha",
      productionType: property.productionType || "Tilápia",
      systemType: property.systemType || "",
      notes: property.notes || ""
    };
  }

  function fillForm(property) {
    var model = getFormModel(property);

    setValue("property_name", model.name);
    setValue("property_ownerName", model.ownerName);
    setValue("property_document", applyCpfCnpjMask(model.document));
    setValue("property_email", model.email);
    setValue("property_phone", applyPhoneMask(model.phone));
    setValue("property_city", model.city);
    setValue("property_state", model.state);
    setValue("property_address", model.address);
    setValue("property_area", model.area);
    setValue("property_areaUnit", model.areaUnit || "ha");
    setValue("property_productionType", model.productionType || "Tilápia");
    setValue("property_systemType", model.systemType);
    setValue("property_notes", model.notes);

    lastAutoState = model.state || "";
    stateManuallyEdited = false;

    setFormMode(!!property);
  }

  function setFormMode(hasProperty) {
    setText(
      "propertyFormTitle",
      hasProperty ? "Editar piscicultura" : "Cadastrar piscicultura"
    );

    setText(
      "propertySubmitText",
      hasProperty ? "Salvar alterações" : "Salvar piscicultura"
    );
  }

  function setSavingState(isSaving) {
    saving = !!isSaving;
    setDisabled("propertySubmitBtn", saving);

    if (saving) {
      setText("propertySubmitText", "Salvando...");
      return;
    }

    setFormMode(!!currentPropertyCache);
  }

  async function reloadSavedProperty(savedProperty) {
    var service = getService();

    if (!service) {
      return savedProperty || null;
    }

    if (
      savedProperty &&
      savedProperty.id &&
      typeof service.getPropertyById === "function"
    ) {
      var byId = await service.getPropertyById(savedProperty.id);

      if (byId) {
        return byId;
      }
    }

    if (typeof service.refreshCurrentPropertySession === "function") {
      var refreshed = await service.refreshCurrentPropertySession();

      if (refreshed) {
        return refreshed;
      }
    }

    if (typeof service.getCurrentProperty === "function") {
      var current = await service.getCurrentProperty();

      if (current) {
        return current;
      }
    }

    return savedProperty || null;
  }

  async function refreshDependentModules() {
    if (
      window.AquaGestApp &&
      typeof window.AquaGestApp.updateAuthStatus === "function"
    ) {
      window.AquaGestApp.updateAuthStatus();
    }

    if (
      window.ViveirosUI &&
      typeof window.ViveirosUI.refreshPropertySuggestion === "function"
    ) {
      await window.ViveirosUI.refreshPropertySuggestion();
    }

    if (
      window.ViveirosUI &&
      typeof window.ViveirosUI.loadPonds === "function"
    ) {
      await window.ViveirosUI.loadPonds();
    }
  }

  async function loadCurrentProperty() {
    if (loading || saving) {
      return currentPropertyCache;
    }

    var service = getService();

    if (!isUserLoggedIn()) {
      currentPropertyCache = null;
      renderSummary(null);
      fillForm(null);
      return null;
    }

    if (
      !service ||
      typeof service.getCurrentProperty !== "function"
    ) {
      currentPropertyCache = null;
      renderSummary(null);
      fillForm(null);
      showMessage("Serviço da Piscicultura não carregado.", "error");
      return null;
    }

    try {
      loading = true;

      await ensureDatabaseReady();

      var property = await service.getCurrentProperty();

      currentPropertyCache = property || null;

      renderSummary(currentPropertyCache);
      fillForm(currentPropertyCache);

      return currentPropertyCache;
    } catch (error) {
      currentPropertyCache = null;
      renderSummary(null);
      fillForm(null);

      showMessage(
        error.message || "Erro ao carregar dados da piscicultura.",
        "error"
      );

      return null;
    } finally {
      loading = false;
    }
  }

  async function handleSubmit(event) {
    event.preventDefault();

    var service = getService();

    if (
      !service ||
      typeof service.saveProperty !== "function"
    ) {
      showMessage("Serviço da Piscicultura não carregado.", "error");
      return;
    }

    try {
      setSavingState(true);

      await ensureDatabaseReady();

      var values = collectPropertyFormValues();
      var savedProperty = await service.saveProperty(values);
      var persistedProperty = await reloadSavedProperty(savedProperty);

      if (!persistedProperty || !persistedProperty.id) {
        throw new Error("A Piscicultura foi enviada para salvar, mas não foi confirmada no banco local.");
      }

      currentPropertyCache = persistedProperty;

      renderSummary(currentPropertyCache);
      fillForm(currentPropertyCache);

      await refreshDependentModules();

      if (
        window.dispatchEvent &&
        typeof CustomEvent === "function"
      ) {
        window.dispatchEvent(new CustomEvent(PROPERTY_CHANGED_EVENT, {
          detail: {
            action: "saved",
            property: currentPropertyCache,
            summary: getSummary(currentPropertyCache)
          }
        }));
      }

      showMessage("Piscicultura salva e confirmada no banco local.", "success");
    } catch (error) {
      showMessage(
        error.message || "Erro ao salvar a piscicultura.",
        "error"
      );
    } finally {
      setSavingState(false);
    }
  }

  function bindForm() {
    var form = getElement("pisciculturaForm");

    if (form) {
      form.addEventListener("submit", handleSubmit);
    }

    bindMasks();
    bindCityStateSuggestion();
  }

  function bindNavigationRefresh() {
    document.addEventListener("click", function (event) {
      var button = event.target.closest('[data-screen="piscicultura"]');

      if (!button) {
        return;
      }

      setTimeout(function () {
        loadCurrentProperty();
      }, 120);
    });
  }

  function bindPropertyChangedEvent() {
    window.addEventListener(PROPERTY_CHANGED_EVENT, function (event) {
      if (saving) {
        return;
      }

      var detail = event.detail || {};
      var property = detail.property || null;

      if (property && property.id) {
        currentPropertyCache = property;
        renderSummary(property);
        fillForm(property);
        return;
      }

      loadCurrentProperty();
    });
  }

  function scheduleInitialLoad() {
    setTimeout(function () {
      loadCurrentProperty();
    }, 400);

    setTimeout(function () {
      loadCurrentProperty();
    }, 1200);
  }

  function init() {
    if (initialized) {
      return;
    }

    initialized = true;

    bindForm();
    bindNavigationRefresh();
    bindPropertyChangedEvent();
    removeOldCityDatalist();
    renderSummary(null);
    setFormMode(false);
    scheduleInitialLoad();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  window.PisciculturaUI = {
    init: init,
    loadCurrentProperty: loadCurrentProperty,
    renderSummary: renderSummary,
    fillForm: fillForm,
    collectPropertyFormValues: collectPropertyFormValues,
    refreshDependentModules: refreshDependentModules,
    suggestStateFromCity: suggestStateFromCity,
    applyCpfCnpjMask: applyCpfCnpjMask,
    applyPhoneMask: applyPhoneMask,
    getCurrentPropertyCache: function () {
      return currentPropertyCache;
    }
  };
})();
;

