(function () {
  "use strict";

  var initialized = false;
  var pondsCache = [];
  var waterHistoryCache = [];
  var editingWaterId = "";
  var loadingEdit = false;
  var previewRequestId = 0;
  var refreshTimer = null;

  var WATER_CHANGED_EVENT = "aquagest:water-quality-changed";
  var PONDS_CHANGED_EVENT = "aquagest:ponds-changed";
  var PROPERTY_CHANGED_EVENT = "aquagest:property-changed";

  function getElement(id) {
    return document.getElementById(id);
  }

  function setValue(id, value) {
    var element = getElement(id);

    if (element) {
      element.value = value === null || value === undefined ? "" : String(value);
    }
  }

  function setText(id, value) {
    var element = getElement(id);

    if (element) {
      element.textContent = value === null || value === undefined ? "" : String(value);
    }
  }

  function showElement(id) {
    var element = getElement(id);

    if (element) {
      element.classList.remove("hidden");
    }
  }

  function hideElement(id) {
    var element = getElement(id);

    if (element) {
      element.classList.add("hidden");
    }
  }

  function showMessage(message, type) {
    if (
      window.AquaGestApp &&
      typeof window.AquaGestApp.showMessage === "function"
    ) {
      window.AquaGestApp.showMessage(message, type || "success");
      return;
    }

    alert(message);
  }

  function escapeHtml(value) {
    return String(value || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function toNumber(value, fallback) {
    /* Leitor único: js/core/number-parser.js (AquaGestNumber). */
    var shared = typeof window !== "undefined" && window.AquaGestNumber;
    if (shared) return shared.parse(value, fallback);
    var fb = fallback === undefined ? 0 : fallback;
    if (value === null || value === undefined || value === "") return fb;
    if (typeof value === "number") return Number.isFinite(value) ? value : fb;
    var text = String(value).trim().replace(/[\s\u00a0]/g, "");
    if (!text) return fb;
    if (text.indexOf(",") >= 0) text = text.replace(/\./g, "").replace(",", ".");
    var parsed = Number(text);
    return Number.isFinite(parsed) ? parsed : fb;
  }

  function formatNumber(value, decimals) {
    var number = Number(value);

    if (!Number.isFinite(number)) {
      number = 0;
    }

    var fixedDecimals = Number.isInteger(decimals) ? decimals : 2;

    return number.toLocaleString("pt-BR", {
      minimumFractionDigits: fixedDecimals,
      maximumFractionDigits: fixedDecimals
    });
  }

  function formatDate(value) {
    if (!value) {
      return "-";
    }

    var parts = String(value).split("-");

    if (parts.length === 3) {
      return parts[2] + "/" + parts[1] + "/" + parts[0];
    }

    return value;
  }

  function todayIsoDate() {
    var now = new Date();
    var year = now.getFullYear();
    var month = String(now.getMonth() + 1).padStart(2, "0");
    var day = String(now.getDate()).padStart(2, "0");

    return year + "-" + month + "-" + day;
  }

  function currentTime() {
    var now = new Date();
    var hour = String(now.getHours()).padStart(2, "0");
    var minute = String(now.getMinutes()).padStart(2, "0");

    return hour + ":" + minute;
  }

  function canTryLoadData() {
    var appArea = getElement("appArea");

    if (appArea && appArea.classList.contains("hidden")) {
      return false;
    }

    if (!window.AuthService) {
      return false;
    }

    try {
      if (
        typeof window.AuthService.getCurrentUser === "function" &&
        !window.AuthService.getCurrentUser()
      ) {
        return false;
      }

      if (
        typeof window.AuthService.getCurrentPropertyId === "function" &&
        !window.AuthService.getCurrentPropertyId()
      ) {
        return false;
      }
    } catch (error) {
      return false;
    }

    return true;
  }

  function isAguaScreenActive() {
    var screen = getElement("screen-agua");

    return !!(screen && screen.classList.contains("active"));
  }

  function isEditingWater() {
    return !!editingWaterId;
  }

  function getSelectedPond() {
    var select = getElement("water_pondId");
    var pondId = select ? select.value : "";

    return pondsCache.find(function (item) {
      return item.pondId === pondId;
    }) || null;
  }

  function setPondSelectLocked(locked) {
    var select = getElement("water_pondId");

    if (select) {
      select.disabled = !!locked;
    }
  }

  function setFormMode(editing) {
    if (editing) {
      setText("waterSubmitText", "Salvar alterações da leitura");
      showElement("waterCancelEditBtn");
      setPondSelectLocked(true);
      return;
    }

    setText("waterSubmitText", "Registrar leitura da água");
    hideElement("waterCancelEditBtn");
    setPondSelectLocked(false);
  }

  function ensureWaterScreenStructure() {
    var screen = getElement("screen-agua");

    if (!screen || getElement("waterQualityForm")) {
      return;
    }

    screen.innerHTML =
      '<div class="page-header">' +
        '<div>' +
          '<h2>Água</h2>' +
          '<p>Controle técnico da qualidade da água por viveiro.</p>' +
        '</div>' +
      '</div>' +

      '<section class="page-card">' +
        '<div class="toolbar">' +
          '<div class="toolbar-title">' +
            '<h3>Registro de qualidade da água</h3>' +
            '<span>Informe os parâmetros medidos no viveiro.</span>' +
          '</div>' +
        '</div>' +

        '<form id="waterQualityForm">' +
          '<input id="water_id" name="id" type="hidden" />' +
          '<input id="water_cycleId" name="cycleId" type="hidden" />' +

          '<div class="form-grid">' +
            '<div>' +
              '<label for="water_pondId">Viveiro</label>' +
              '<select id="water_pondId" name="pondId" required>' +
                '<option value="">Selecione o viveiro</option>' +
              '</select>' +
            '</div>' +

            '<div>' +
              '<label for="water_date">Data da leitura</label>' +
              '<input id="water_date" name="date" type="date" required />' +
            '</div>' +

            '<div>' +
              '<label for="water_time">Hora da leitura</label>' +
              '<input id="water_time" name="time" type="time" required />' +
            '</div>' +

            '<div>' +
              '<label for="water_temperatureC">Temperatura da água (°C)</label>' +
              '<input id="water_temperatureC" name="temperatureC" type="number" step="0.1" inputmode="decimal" required />' +
            '</div>' +

            '<div>' +
              '<label for="water_dissolvedOxygenMgL">Oxigênio dissolvido (mg/L)</label>' +
              '<input id="water_dissolvedOxygenMgL" name="dissolvedOxygenMgL" type="number" step="0.01" inputmode="decimal" required />' +
            '</div>' +

            '<div>' +
              '<label for="water_ph">pH</label>' +
              '<input id="water_ph" name="ph" type="number" step="0.01" inputmode="decimal" required />' +
            '</div>' +

            '<div>' +
              '<label for="water_tanMgL">TAN — nitrogênio amoniacal total (mg/L)</label>' +
              '<input id="water_tanMgL" name="tanMgL" type="number" step="0.001" inputmode="decimal" placeholder="Opcional" />' +
            '</div>' +

            '<div>' +
              '<label for="water_nh3MgL">NH3 — amônia não ionizada (mg/L)</label>' +
              '<input id="water_nh3MgL" name="nh3MgL" type="number" step="0.0001" inputmode="decimal" placeholder="Calculada pelo TAN, pH e temperatura" />' +
            '</div>' +

            '<div>' +
              '<label for="water_nitriteMgL">Nitrito (mg/L)</label>' +
              '<input id="water_nitriteMgL" name="nitriteMgL" type="number" step="0.001" inputmode="decimal" placeholder="Opcional" />' +
            '</div>' +

            '<div>' +
              '<label for="water_alkalinityMgL">Alcalinidade (mg/L CaCO₃)</label>' +
              '<input id="water_alkalinityMgL" name="alkalinityMgL" type="number" step="0.01" inputmode="decimal" placeholder="Opcional" />' +
            '</div>' +

            '<div>' +
              '<label for="water_technicalStatus">Classificação</label>' +
              '<input id="water_technicalStatus" name="technicalStatus" type="text" readonly value="Aguardando dados" />' +
            '</div>' +
          '</div>' +

          '<div>' +
            '<label for="water_notes">Observações</label>' +
            '<textarea id="water_notes" name="notes" rows="3" placeholder="Ex.: comportamento dos peixes, coloração da água, aeração ligada, chuva recente..."></textarea>' +
          '</div>' +

          '<div class="form-actions">' +
            '<button id="waterSubmitBtn" class="primary-btn" type="submit">' +
              '<span id="waterSubmitText">Registrar leitura da água</span>' +
            '</button>' +
            '<button id="waterCancelEditBtn" class="secondary-btn hidden" type="button">Cancelar edição</button>' +
          '</div>' +
        '</form>' +
      '</section>' +

      '<section id="waterPreviewBox" class="page-card hidden">' +
        '<div class="toolbar">' +
          '<div class="toolbar-title">' +
            '<h3>Prévia técnica</h3>' +
            '<span>Classificação automática antes de salvar.</span>' +
          '</div>' +
        '</div>' +
        '<div id="waterPreviewList"></div>' +
      '</section>' +

      '<section id="waterRecommendationsPreview" class="page-card hidden">' +
        '<div class="toolbar">' +
          '<div class="toolbar-title">' +
            '<h3>Recomendações técnicas</h3>' +
            '<span>Orientações geradas pela leitura da água.</span>' +
          '</div>' +
        '</div>' +
        '<div id="waterRecommendationsList"></div>' +
      '</section>' +

      '<section class="page-card">' +
        '<div class="toolbar">' +
          '<div class="toolbar-title">' +
            '<h3>Histórico de qualidade da água</h3>' +
            '<span>Leituras registradas por viveiro.</span>' +
          '</div>' +
        '</div>' +
        '<div id="waterEmptyState" class="empty-state">Nenhuma leitura de água registrada.</div>' +
        '<div id="waterListWrapper" class="hidden"></div>' +
      '</section>';
  }

  function collectFormValues() {
    var pond = getSelectedPond();

    return {
      id: getElement("water_id") ? getElement("water_id").value : "",

      pondId: getElement("water_pondId") ? getElement("water_pondId").value : "",
      cycleId: getElement("water_cycleId") ? getElement("water_cycleId").value : "",

      date: getElement("water_date") ? getElement("water_date").value : "",
      time: getElement("water_time") ? getElement("water_time").value : "",

      temperatureC: getElement("water_temperatureC") ? getElement("water_temperatureC").value : "",
      dissolvedOxygenMgL: getElement("water_dissolvedOxygenMgL") ? getElement("water_dissolvedOxygenMgL").value : "",
      ph: getElement("water_ph") ? getElement("water_ph").value : "",

      tanMgL: getElement("water_tanMgL") ? getElement("water_tanMgL").value : "",
      nh3MgL: getElement("water_nh3MgL") ? getElement("water_nh3MgL").value : "",
      nitriteMgL: getElement("water_nitriteMgL") ? getElement("water_nitriteMgL").value : "",
      alkalinityMgL: getElement("water_alkalinityMgL") ? getElement("water_alkalinityMgL").value : "",

      notes: getElement("water_notes") ? getElement("water_notes").value : "",

      pondName: pond ? pond.pondName : ""
    };
  }

  function updateHiddenCycleField() {
    var pond = getSelectedPond();

    setValue("water_cycleId", pond ? pond.currentCycleId || "" : "");
  }

  function clearForm() {
    var form = getElement("waterQualityForm");

    editingWaterId = "";

    if (form) {
      form.reset();
    }

    setValue("water_id", "");
    setValue("water_pondId", "");
    setValue("water_cycleId", "");
    setValue("water_date", todayIsoDate());
    setValue("water_time", currentTime());

    setValue("water_temperatureC", "");
    setValue("water_dissolvedOxygenMgL", "");
    setValue("water_ph", "");
    setValue("water_tanMgL", "");
    setValue("water_nh3MgL", "");
    setValue("water_nitriteMgL", "");
    setValue("water_alkalinityMgL", "");
    setValue("water_notes", "");

    setValue("water_technicalStatus", "Aguardando dados");

    resetPreview();
    setFormMode(false);
  }

  function getSeverityBadgeClass(severity) {
    if (severity === "critical") return "badge danger";
    if (severity === "warning") return "badge warning";
    if (severity === "normal") return "badge success";
    return "badge";
  }

  function translateSeverityLabel(severity) {
    if (severity === "critical") return "Crítico";
    if (severity === "warning") return "Atenção";
    if (severity === "normal") return "Normal";
    if (severity === "pending") return "Aguardando dados";

    return "Técnico";
  }

  function formatParameterValue(item) {
    if (!item || item.severity === "pending") {
      return "Não informado";
    }

    var decimals = item.key === "temperatureC" ? 1 : 3;
    var value = formatNumber(item.value || 0, decimals);

    return item.unit ? value + " " + item.unit : value;
  }

  function buildParameterResultsHtml(parameterResults) {
    var results = parameterResults || [];

    if (!results.length) {
      return "";
    }

    var html = '<div class="pond-metrics-grid">';

    results.forEach(function (item) {
      html +=
        '<div class="pond-metric">' +
          '<strong>' + escapeHtml(item.label || "Parâmetro") + '</strong>' +
          '<span>' + escapeHtml(formatParameterValue(item)) + '</span>' +
          '<small>' + escapeHtml(item.status || "") + '</small>' +
        '</div>';
    });

    html += '</div>';

    return html;
  }

  function normalizeRecommendations(source) {
    var item = source || {};
    var recommendations = item.technicalRecommendations;

    if (Array.isArray(recommendations) && recommendations.length > 0) {
      return recommendations;
    }

    if (item.technicalRecommendationsText) {
      return String(item.technicalRecommendationsText)
        .split("\n")
        .filter(function (line) {
          return !!String(line || "").trim();
        })
        .map(function (line) {
          return {
            severity: item.technicalSeverity || "normal",
            title: "Recomendação técnica",
            message: line
          };
        });
    }

    if (item.technicalMessage) {
      return [{
        severity: item.technicalSeverity || "normal",
        title: item.technicalStatus || "Situação técnica",
        message: item.technicalMessage
      }];
    }

    return [];
  }

  function buildRecommendationsHtml(source) {
    var recommendations = normalizeRecommendations(source);

    if (!recommendations.length) {
      return "";
    }

    var html = '<div class="recommendation-list">';

    recommendations.forEach(function (item) {
      html +=
        '<div class="recommendation-item">' +
          '<span class="' + escapeHtml(getSeverityBadgeClass(item.severity)) + '">' +
            escapeHtml(translateSeverityLabel(item.severity)) +
          '</span>' +
          '<div>' +
            '<strong>' + escapeHtml(item.title || "Recomendação técnica") + '</strong>' +
            '<span>' + escapeHtml(item.message || "") + '</span>' +
          '</div>' +
        '</div>';
    });

    html += '</div>';

    return html;
  }

  function renderPreview(metrics) {
    var item = metrics || {};
    var previewBox = getElement("waterPreviewBox");
    var previewList = getElement("waterPreviewList");
    var recommendationsBox = getElement("waterRecommendationsPreview");
    var recommendationsList = getElement("waterRecommendationsList");

    setValue("water_technicalStatus", item.technicalStatus || "Aguardando dados");

    if (previewBox && previewList) {
      previewList.innerHTML =
        '<div class="pond-card-header">' +
          '<div>' +
            '<h4>' + escapeHtml(item.technicalStatus || "Aguardando dados") + '</h4>' +
            '<span>' + escapeHtml(item.technicalMessage || "") + '</span>' +
          '</div>' +
          '<span class="' + escapeHtml(getSeverityBadgeClass(item.technicalSeverity)) + '">' +
            escapeHtml(translateSeverityLabel(item.technicalSeverity)) +
          '</span>' +
        '</div>' +

        '<div class="pond-card-info">' +
          '<strong>Fator técnico para arraçoamento</strong>' +
          '<span>' +
            escapeHtml(item.recommendedFeedingAction || "Aguardando dados") +
            ' — fator ' + escapeHtml(formatNumber(item.waterFeedingFactor || 0, 2)) +
          '</span>' +
        '</div>' +

        buildParameterResultsHtml(item.parameterResults || []);

      showElement("waterPreviewBox");
    }

    if (recommendationsBox && recommendationsList) {
      var recommendationsHtml = buildRecommendationsHtml(item);

      if (recommendationsHtml) {
        recommendationsList.innerHTML = recommendationsHtml;
        showElement("waterRecommendationsPreview");
      } else {
        recommendationsList.innerHTML = "";
        hideElement("waterRecommendationsPreview");
      }
    }
  }

  function resetPreview() {
    var previewList = getElement("waterPreviewList");
    var recommendationsList = getElement("waterRecommendationsList");

    if (previewList) {
      previewList.innerHTML = "";
    }

    if (recommendationsList) {
      recommendationsList.innerHTML = "";
    }

    hideElement("waterPreviewBox");
    hideElement("waterRecommendationsPreview");
  }

  async function updatePreview() {
    if (
      !window.AguaService ||
      typeof window.AguaService.calculateWaterQualityPreview !== "function"
    ) {
      resetPreview();
      return;
    }

    updateHiddenCycleField();

    var values = collectFormValues();

    if (!values.pondId) {
      resetPreview();
      return;
    }

    var currentRequestId = previewRequestId + 1;
    previewRequestId = currentRequestId;

    try {
      var result = await window.AguaService.calculateWaterQualityPreview(values);

      if (currentRequestId !== previewRequestId) {
        return;
      }

      renderPreview(result && result.metrics ? result.metrics : {});
    } catch (error) {
      if (currentRequestId !== previewRequestId) {
        return;
      }

      setValue("water_technicalStatus", error.message || "Erro ao classificar água");
    }
  }

  function describePondOption(item) {
    var pondName = item.pondName || "Viveiro";
    var cycle = item.currentCycleId ? "Lote ativo" : "Sem lote ativo";

    return pondName + " — " + cycle;
  }

  async function loadPonds(selectedPondId) {
    var select = getElement("water_pondId");

    if (!select) {
      return;
    }

    if (
      !window.AguaService ||
      typeof window.AguaService.listPondsForWaterQuality !== "function"
    ) {
      select.innerHTML = '<option value="">Serviço de Água não carregado</option>';
      pondsCache = [];
      return;
    }

    if (!canTryLoadData()) {
      select.innerHTML = '<option value="">Selecione o viveiro</option>';
      pondsCache = [];
      return;
    }

    try {
      var previousValue = selectedPondId || select.value || "";

      pondsCache = await window.AguaService.listPondsForWaterQuality();

      select.innerHTML = '<option value="">Selecione o viveiro</option>';

      pondsCache.forEach(function (item) {
        var option = document.createElement("option");

        option.value = item.pondId;
        option.textContent = describePondOption(item);

        select.appendChild(option);
      });

      if (pondsCache.length === 0) {
        var emptyOption = document.createElement("option");

        emptyOption.value = "";
        emptyOption.textContent = "Nenhum viveiro ativo disponível";

        select.appendChild(emptyOption);
      }

      var previousExists = pondsCache.some(function (item) {
        return item.pondId === previousValue;
      });

      if (previousExists) {
        select.value = previousValue;
      }

      updateHiddenCycleField();
    } catch (error) {
      select.innerHTML = '<option value="">Erro ao carregar viveiros</option>';
      pondsCache = [];
      showMessage(error.message || "Erro ao carregar viveiros para qualidade da água.", "error");
    }
  }

  function buildNotesHtml(notes) {
    if (!notes) {
      return "";
    }

    return (
      '<div class="pond-card-info">' +
        '<strong>Observações</strong>' +
        '<span>' + escapeHtml(notes) + '</span>' +
      '</div>'
    );
  }

  function renderWaterHistory(records) {
    var wrapper = getElement("waterListWrapper");

    if (!wrapper) {
      return;
    }

    wrapper.innerHTML = "";

    if (!records || records.length === 0) {
      showElement("waterEmptyState");
      hideElement("waterListWrapper");
      return;
    }

    hideElement("waterEmptyState");
    showElement("waterListWrapper");

    var list = document.createElement("div");
    list.className = "pond-card-list";

    records.forEach(function (record) {
      var card = document.createElement("article");
      card.className = "pond-card water-card";

      card.innerHTML =
        '<div class="pond-card-header">' +
          '<div>' +
            '<h4>' + escapeHtml(record.pondName || "Viveiro") + '</h4>' +
            '<span>' + escapeHtml(formatDate(record.date)) + ' às ' + escapeHtml(record.time || "-") + '</span>' +
          '</div>' +
          '<span class="' + escapeHtml(getSeverityBadgeClass(record.technicalSeverity)) + '">' +
            escapeHtml(record.technicalStatus || "Não informado") +
          '</span>' +
        '</div>' +

        '<div class="pond-metrics-grid">' +
          '<div class="pond-metric">' +
            '<strong>Temperatura</strong>' +
            '<span>' + escapeHtml(formatNumber(record.temperatureC || 0, 1)) + ' °C</span>' +
          '</div>' +

          '<div class="pond-metric">' +
            '<strong>Oxigênio dissolvido</strong>' +
            '<span>' + escapeHtml(formatNumber(record.dissolvedOxygenMgL || 0, 2)) + ' mg/L</span>' +
          '</div>' +

          '<div class="pond-metric">' +
            '<strong>pH</strong>' +
            '<span>' + escapeHtml(formatNumber(record.ph || 0, 2)) + '</span>' +
          '</div>' +

          '<div class="pond-metric">' +
            '<strong>TAN / NH3</strong>' +
            '<span>' + escapeHtml(record.hasTanMgL ? "TAN " + formatNumber(record.tanMgL || 0, 3) + " mg/L · NH3 " + formatNumber(record.nh3MgL || 0, 4) + " mg/L" : "Não informado") + '</span>' +
          '</div>' +

          '<div class="pond-metric">' +
            '<strong>Nitrito</strong>' +
            '<span>' + escapeHtml(record.hasNitriteMgL ? formatNumber(record.nitriteMgL || 0, 3) + " mg/L" : "Não informado") + '</span>' +
          '</div>' +

          '<div class="pond-metric">' +
            '<strong>Alcalinidade</strong>' +
            '<span>' + escapeHtml(record.hasAlkalinityMgL ? formatNumber(record.alkalinityMgL || 0, 2) + " mg/L CaCO₃" : "Não informada") + '</span>' +
          '</div>' +
        '</div>' +

        '<div class="pond-card-info">' +
          '<strong>Fator técnico para arraçoamento</strong>' +
          '<span>' +
            escapeHtml(record.recommendedFeedingAction || "Não informado") +
            ' — fator ' + escapeHtml(formatNumber(record.waterFeedingFactor || 0, 2)) +
          '</span>' +
        '</div>' +

        '<div class="pond-card-info">' +
          '<strong>Mensagem técnica</strong>' +
          '<span>' + escapeHtml(record.technicalMessage || "") + '</span>' +
        '</div>' +

        '<div class="pond-card-info">' +
          '<strong>Parâmetros avaliados</strong>' +
          buildParameterResultsHtml(record.parameterResults || []) +
        '</div>' +

        '<div class="pond-card-info">' +
          '<strong>Recomendações técnicas</strong>' +
          buildRecommendationsHtml(record) +
        '</div>' +

        buildNotesHtml(record.notes) +

        '<div class="pond-card-actions">' +
          '<button class="secondary-btn" type="button" data-water-action="edit" data-water-id="' + escapeHtml(record.id) + '">' +
            'Editar leitura' +
          '</button>' +
          '<button class="secondary-btn" type="button" data-water-action="void" data-water-id="' + escapeHtml(record.id) + '">' +
            'Cancelar registro' +
          '</button>' +
        '</div>';

      list.appendChild(card);
    });

    wrapper.appendChild(list);
  }

  async function loadWaterHistory(options) {
    if (
      !window.AguaService ||
      typeof window.AguaService.listWaterQualityRecords !== "function"
    ) {
      waterHistoryCache = [];
      renderWaterHistory([]);
      return;
    }

    if (!canTryLoadData()) {
      waterHistoryCache = [];
      renderWaterHistory([]);
      return;
    }

    try {
      var opts = options || {};
      var pondId = opts.pondId || "";

      waterHistoryCache = await window.AguaService.listWaterQualityRecords({
        pondId: pondId
      });

      renderWaterHistory(waterHistoryCache);
    } catch (error) {
      waterHistoryCache = [];
      renderWaterHistory([]);
      showMessage(error.message || "Erro ao carregar histórico de água.", "error");
    }
  }

  async function refreshWaterScreen() {
    await loadPonds(getElement("water_pondId") ? getElement("water_pondId").value : "");

    var selectedPondId = getElement("water_pondId") ? getElement("water_pondId").value : "";

    await loadWaterHistory({
      pondId: selectedPondId
    });

    await updatePreview();
  }

  function scheduleRefresh() {
    clearTimeout(refreshTimer);

    refreshTimer = setTimeout(function () {
      if (isAguaScreenActive()) {
        refreshWaterScreen();
      }
    }, 150);
  }

  async function startEditWater(id) {
    if (!id || loadingEdit) {
      return;
    }

    if (
      !window.AguaService ||
      typeof window.AguaService.getWaterQualityById !== "function"
    ) {
      showMessage("Serviço de Água não carregado.", "error");
      return;
    }

    try {
      loadingEdit = true;

      var record = await window.AguaService.getWaterQualityById(id);

      editingWaterId = record.id || "";

      await loadPonds(record.pondId || "");

      setValue("water_id", record.id || "");
      setValue("water_pondId", record.pondId || "");
      setValue("water_cycleId", record.cycleId || record.productionCycleId || "");

      setValue("water_date", record.date || todayIsoDate());
      setValue("water_time", record.time || currentTime());

      setValue("water_temperatureC", record.temperatureC || "");
      setValue("water_dissolvedOxygenMgL", record.dissolvedOxygenMgL || "");
      setValue("water_ph", record.ph || "");
      setValue("water_tanMgL", record.hasTanMgL ? record.tanMgL || "" : record.ammoniaTotalMgL || "");
      setValue("water_nh3MgL", record.hasNh3MgL ? record.nh3MgL || "" : "");
      setValue("water_nitriteMgL", record.hasNitriteMgL ? record.nitriteMgL || "" : "");
      setValue("water_alkalinityMgL", record.hasAlkalinityMgL ? record.alkalinityMgL || "" : "");
      setValue("water_notes", record.notes || "");

      setFormMode(true);

      await updatePreview();

      var form = getElement("waterQualityForm");

      if (form && typeof form.scrollIntoView === "function") {
        form.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      }

      showMessage("Leitura de água carregada para edição.", "warning");
    } catch (error) {
      showMessage(error.message || "Erro ao carregar leitura para edição.", "error");
    } finally {
      loadingEdit = false;
    }
  }

  async function cancelEdit() {
    clearForm();
    await refreshWaterScreen();
    showMessage("Edição da leitura cancelada.", "warning");
  }

  async function voidWater(id) {
    if (!id) {
      return;
    }

    if (
      !window.AguaService ||
      typeof window.AguaService.voidWaterQuality !== "function"
    ) {
      showMessage("Função de cancelamento da leitura não carregada.", "error");
      return;
    }

    var confirmed = window.confirm(
      "Cancelar este registro de água? O viveiro será atualizado com a última leitura válida restante."
    );

    if (!confirmed) {
      return;
    }

    try {
      await window.AguaService.voidWaterQuality(id, "Registro cancelado pela interface.");

      showMessage("Registro de água cancelado e viveiro atualizado.", "success");

      clearForm();
      await refreshWaterScreen();

      if (
        window.ViveirosUI &&
        typeof window.ViveirosUI.loadPonds === "function"
      ) {
        await window.ViveirosUI.loadPonds();
      }
    } catch (error) {
      showMessage(error.message || "Erro ao cancelar leitura de água.", "error");
    }
  }

  async function handleSubmit(event) {
    event.preventDefault();

    if (
      !window.AguaService ||
      typeof window.AguaService.saveWaterQuality !== "function"
    ) {
      showMessage("Serviço de Água não carregado ou desatualizado.", "error");
      return;
    }

    var submitBtn = getElement("waterSubmitBtn");
    var editing = isEditingWater();

    try {
      if (submitBtn) {
        submitBtn.disabled = true;
      }

      setText("waterSubmitText", editing ? "Salvando alterações..." : "Registrando...");

      updateHiddenCycleField();

      var values = collectFormValues();

      if (editingWaterId) {
        values.id = editingWaterId;
      }

      await window.AguaService.saveWaterQuality(values);

      showMessage(
        editing ? "Leitura de água atualizada com sucesso." : "Leitura de água registrada com sucesso.",
        "success"
      );

      clearForm();
      await refreshWaterScreen();

      if (
        window.ViveirosUI &&
        typeof window.ViveirosUI.loadPonds === "function"
      ) {
        await window.ViveirosUI.loadPonds();
      }
    } catch (error) {
      showMessage(error.message || "Erro ao salvar leitura de água.", "error");
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
      }

      setFormMode(isEditingWater());
      await updatePreview();
    }
  }

  function handleHistoryClick(event) {
    var target = event.target;

    if (!target || !target.closest) {
      return;
    }

    var button = target.closest("[data-water-action]");

    if (!button) {
      return;
    }

    var action = button.getAttribute("data-water-action");
    var id = button.getAttribute("data-water-id");

    if (action === "edit") {
      startEditWater(id);
    }

    if (action === "void") {
      voidWater(id);
    }
  }

  function bindCalculationFields() {
    [
      "water_pondId",
      "water_date",
      "water_time",
      "water_temperatureC",
      "water_dissolvedOxygenMgL",
      "water_ph",
      "water_tanMgL",
      "water_nitriteMgL",
      "water_alkalinityMgL"
    ].forEach(function (id) {
      var element = getElement(id);

      if (!element) {
        return;
      }

      element.addEventListener("input", function () {
        updatePreview();
      });

      element.addEventListener("change", function () {
        if (id === "water_pondId") {
          updateHiddenCycleField();

          loadWaterHistory({
            pondId: element.value
          });
        }

        updatePreview();
      });
    });
  }

  function bindForm() {
    var form = getElement("waterQualityForm");

    if (form) {
      form.addEventListener("submit", handleSubmit);
    }

    var cancelBtn = getElement("waterCancelEditBtn");

    if (cancelBtn) {
      cancelBtn.addEventListener("click", function () {
        cancelEdit();
      });
    }

    var wrapper = getElement("waterListWrapper");

    if (wrapper) {
      wrapper.addEventListener("click", handleHistoryClick);
    }

    bindCalculationFields();
  }

  function bindNavigationRefresh() {
    document.addEventListener("click", function (event) {
      var target = event.target;

      if (!target || !target.closest) {
        return;
      }

      var button = target.closest('[data-screen="agua"]');

      if (!button) {
        return;
      }

      setTimeout(function () {
        refreshWaterScreen();
      }, 160);
    });
  }

  function bindExternalRefreshEvents() {
    window.addEventListener(WATER_CHANGED_EVENT, function () {
      scheduleRefresh();
    });

    window.addEventListener(PONDS_CHANGED_EVENT, function () {
      scheduleRefresh();
    });

    window.addEventListener(PROPERTY_CHANGED_EVENT, function () {
      clearForm();
      scheduleRefresh();
    });
  }

  function init() {
    if (initialized) {
      return;
    }

    initialized = true;

    ensureWaterScreenStructure();
    bindForm();
    bindNavigationRefresh();
    bindExternalRefreshEvents();

    clearForm();

    setTimeout(function () {
      if (isAguaScreenActive()) {
        refreshWaterScreen();
      }
    }, 500);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  window.AguaUI = {
    init: init,

    loadPonds: loadPonds,
    loadWaterHistory: loadWaterHistory,
    refreshWaterScreen: refreshWaterScreen,

    updatePreview: updatePreview,
    clearForm: clearForm,

    startEditWater: startEditWater,
    cancelEdit: cancelEdit,
    voidWater: voidWater
  };
})();

;

