  function ensureNutritionGuide() {
    var screen = getElement("screen-arracoamento");

    if (!screen || getElement("feedingNutritionGuide")) {
      return;
    }

    var guideWrapper = document.createElement("div");
    guideWrapper.innerHTML = buildNutritionGuideHtml();

    var guide = guideWrapper.firstChild;
    var firstCard = screen.querySelector(".page-card");

    if (firstCard) {
      firstCard.insertAdjacentElement("beforebegin", guide);
    } else {
      screen.appendChild(guide);
    }
  }

  function ensureInventoryControl() {
    if (getElement("feeding_inventoryItemId")) {
      return;
    }

    var feedNameInput = getElement("feeding_feedName");

    if (!feedNameInput) {
      return;
    }

    var feedNameWrapper = feedNameInput.closest("div");

    if (!feedNameWrapper || !feedNameWrapper.parentNode) {
      return;
    }

    var wrapper = document.createElement("div");
    wrapper.className = "feeding-inventory-field";

    wrapper.innerHTML =
      '<label for="feeding_inventoryItemId">Item do estoque usado</label>' +
      '<select id="feeding_inventoryItemId" name="inventoryItemId">' +
        '<option value="">Selecione a ração do estoque</option>' +
      '</select>';

    feedNameWrapper.insertAdjacentElement("beforebegin", wrapper);
  }

  function ensureFeedProfileControls() {
    var feedNameInput = getElement("feeding_feedName");

    if (!feedNameInput) {
      return;
    }

    var feedNameWrapper = feedNameInput.closest("div");

    if (!feedNameWrapper || !feedNameWrapper.parentNode) {
      return;
    }

    if (!getElement("feeding_feedPhase")) {
      var wrapper = document.createElement("div");
      wrapper.className = "feeding-profile-fields";

      wrapper.innerHTML =
        '<div>' +
          '<label for="feeding_feedPhysicalType">Tipo físico da ração</label>' +
          '<select id="feeding_feedPhysicalType" name="feedPhysicalType">' +
            getPhysicalTypeOptionsHtml() +
          '</select>' +
        '</div>' +

        '<div>' +
          '<label for="feeding_feedPhase">Fase da ração</label>' +
          '<select id="feeding_feedPhase" name="feedPhase">' +
            getFeedPhaseOptionsHtml() +
          '</select>' +
        '</div>' +

        '<div>' +
          '<label for="feeding_crudeProteinPercent">Proteína bruta da ração (%)</label>' +
          '<input id="feeding_crudeProteinPercent" name="crudeProteinPercent" type="text" inputmode="decimal" placeholder="Ex.: 32" />' +
        '</div>' +

        '<div>' +
          '<label for="feeding_pelletSizeMm">Granulometria / pellet (mm)</label>' +
          '<input id="feeding_pelletSizeMm" name="pelletSizeMm" type="text" inputmode="decimal" placeholder="Ex.: 3" />' +
        '</div>';

      feedNameWrapper.insertAdjacentElement("afterend", wrapper);
    }

    if (!getElement("feeding_feedPhysicalType")) {
      var phaseElement = getElement("feeding_feedPhase");
      var phaseWrapper = phaseElement ? phaseElement.closest("div") : null;

      if (phaseWrapper && phaseWrapper.parentNode) {
        var physicalWrapper = document.createElement("div");
        physicalWrapper.className = "feeding-physical-type-field";

        physicalWrapper.innerHTML =
          '<label for="feeding_feedPhysicalType">Tipo físico da ração</label>' +
          '<select id="feeding_feedPhysicalType" name="feedPhysicalType">' +
            getPhysicalTypeOptionsHtml() +
          '</select>';

        phaseWrapper.insertAdjacentElement("beforebegin", physicalWrapper);
      }
    }

    updatePhysicalTypeOptions();
    updateFeedPhaseOptions();
  }

  function collectFormValues() {
    return {
      id: getElement("feeding_id") ? getElement("feeding_id").value : "",

      cycleId: getElement("feeding_activeLotId") ? getElement("feeding_activeLotId").value : "",
      pondId: getElement("feeding_pondIdHidden") ? getElement("feeding_pondIdHidden").value : "",

      inventoryItemId: getElement("feeding_inventoryItemId") ? getElement("feeding_inventoryItemId").value : "",
      feedInventoryItemId: getElement("feeding_inventoryItemId") ? getElement("feeding_inventoryItemId").value : "",

      date: getElement("feeding_date") ? getElement("feeding_date").value : "",
      time: getElement("feeding_time") ? getElement("feeding_time").value : "",

      feedName: getElement("feeding_feedName") ? getElement("feeding_feedName").value : "",
      feedPhysicalType: getElement("feeding_feedPhysicalType") ? getElement("feeding_feedPhysicalType").value : "",
      feedPhase: getElement("feeding_feedPhase") ? getElement("feeding_feedPhase").value : "",
      crudeProteinPercent: getElement("feeding_crudeProteinPercent") ? getElement("feeding_crudeProteinPercent").value : "",
      pelletSizeMm: getElement("feeding_pelletSizeMm") ? getElement("feeding_pelletSizeMm").value : "",

      mealsPerDay: getElement("feeding_mealsPerDay") ? getElement("feeding_mealsPerDay").value : "",
      mealsPerformed: getElement("feeding_mealsPerformed") ? getElement("feeding_mealsPerformed").value : "",

      feedProvidedKg: getElement("feeding_feedProvidedKg") ? getElement("feeding_feedProvidedKg").value : "",
      feedWasteKg: getElement("feeding_feedWasteKg") ? getElement("feeding_feedWasteKg").value : "",
      mortalityCount: getElement("feeding_mortality") ? getElement("feeding_mortality").value : "",
      temperatureC: getElement("feeding_temperatureC") ? getElement("feeding_temperatureC").value : "",

      notes: getElement("feeding_notes") ? getElement("feeding_notes").value : ""
    };
  }

  function updateHiddenLotFields() {
    var lot = getSelectedLot();

    setValue("feeding_cycleId", lot ? lot.cycleId || "" : "");
    setValue("feeding_pondIdHidden", lot ? lot.pondId || "" : "");

    if (lot && getElement("feeding_mealsPerDay") && !getElement("feeding_mealsPerDay").value) {
      setValue("feeding_mealsPerDay", lot.mealsPerDay || 2);
    }

    if (lot && getElement("feeding_mealsPerformed") && !getElement("feeding_mealsPerformed").value) {
      setValue("feeding_mealsPerformed", lot.mealsPerDay || 2);
    }
  }

  function applySelectedInventoryItemToForm() {
    var item = getSelectedFeedInventoryItem();

    if (!item) {
      return;
    }

    var feedName = getElement("feeding_feedName");
    var physicalType = getElement("feeding_feedPhysicalType");
    var feedPhase = getElement("feeding_feedPhase");
    var protein = getElement("feeding_crudeProteinPercent");
    var pellet = getElement("feeding_pelletSizeMm");

    if (feedName && !feedName.value) {
      feedName.value = item.itemName || item.name || "";
    }

    if (physicalType && !physicalType.value) {
      physicalType.value = normalizeFeedPhysicalType(
        item.feedPhysicalType ||
        item.physicalType ||
        item.feedType ||
        item.rationPhysicalType ||
        ""
      );
    }

    if (feedPhase && !feedPhase.value) {
      feedPhase.value = normalizeFeedPhase(
        item.feedPhase ||
        item.recommendedFeedPhase ||
        item.rationPhase ||
        ""
      );
    }

    if (protein && !protein.value) {
      protein.value = item.crudeProteinPercent || item.proteinPercent || "";
    }

    if (pellet && !pellet.value) {
      pellet.value = item.pelletSizeMm || item.granulometryMm || "";
    }
  }

  function clearForm() {
    var form = getElement("feedingForm");

    editingFeedingId = "";

    if (form) {
      form.reset();
    }

    setValue("feeding_id", "");
    setValue("feeding_cycleId", "");
    setValue("feeding_pondIdHidden", "");
    setValue("feeding_activeLotId", "");
    setValue("feeding_inventoryItemId", "");

    setValue("feeding_date", todayIsoDate());
    setValue("feeding_time", currentTime());

    setValue("feeding_feedName", "");
    setValue("feeding_feedPhysicalType", "");
    setValue("feeding_feedPhase", "");
    setValue("feeding_crudeProteinPercent", "");
    setValue("feeding_pelletSizeMm", "");

    setValue("feeding_mealsPerDay", "2");
    setValue("feeding_mealsPerformed", "2");
    setValue("feeding_feedProvidedKg", "");
    setValue("feeding_feedWasteKg", "0");
    setValue("feeding_mortality", "0");
    setValue("feeding_temperatureC", "");
    setValue("feeding_notes", "");

    setValue("feeding_recommendedFeedDayKg", "0,000");
    setValue("feeding_waterFactor", "1,00");
    setValue("feeding_adjustedRecommendedFeedKg", "0,000");
    setValue("feeding_recommendedFeedMealKg", "0,000");
    setValue("feeding_technicalStatus", "Aguardando dados");

    resetPreview();
    setFormMode(false);
  }

  function getSeverityBadgeClass(severity) {
    if (severity === "critical") return "badge danger";
    if (severity === "warning") return "badge warning";
    if (severity === "normal") return "badge success";

    return "badge";
  }

  function translateSeverityLabel(severity) {
    if (severity === "critical") return "Crítico";
    if (severity === "warning") return "Atenção";
    if (severity === "normal") return "Normal";
    if (severity === "pending") return "Aguardando dados";

    return "Técnico";
  }

  function normalizeRecommendations(source) {
    var item = source || {};
    var recommendations = item.technicalRecommendations;

    if (Array.isArray(recommendations) && recommendations.length > 0) {
      return recommendations;
    }

    if (item.technicalRecommendationsText) {
      return String(item.technicalRecommendationsText)
        .split("\n")
        .filter(function (line) {
          return !!String(line || "").trim();
        })
        .map(function (line) {
          return {
            severity: item.technicalSeverity || "normal",
            title: "Recomendação técnica",
            message: line
          };
        });
    }

    if (item.technicalMessage) {
      return [{
        severity: item.technicalSeverity || "normal",
        title: item.technicalStatus || "Situação técnica",
        message: item.technicalMessage
      }];
    }

    return [];
  }

  function buildRecommendationsHtml(source) {
    var recommendations = normalizeRecommendations(source);

    if (!recommendations.length) {
      return "";
    }

    var html = '<div class="recommendation-list">';

    recommendations.forEach(function (item) {
      html +=
        '<div class="recommendation-item">' +
          '<span class="' + escapeHtml(getSeverityBadgeClass(item.severity)) + '">' +
            escapeHtml(translateSeverityLabel(item.severity)) +
          '</span>' +
          '<div>' +
            '<strong>' + escapeHtml(item.title || "Recomendação técnica") + '</strong>' +
            '<span>' + escapeHtml(item.message || "") + '</span>' +
          '</div>' +
        '</div>';
    });

    html += '</div>';

    return html;
  }

