  function organizeFinanceiroViews(screen) {
    if (!screen || getElement("financeiroSubnav")) {
      return;
    }

    var periodCard = screen.querySelector("#financeiro_startDate") && screen.querySelector("#financeiro_startDate").closest(".page-card");
    var summary = screen.querySelector(".finance-summary-grid");
    var accountFormCard = screen.querySelector("#financialAccountForm") && screen.querySelector("#financialAccountForm").closest(".page-card");
    var transactionFormCard = screen.querySelector("#financialTransactionForm") && screen.querySelector("#financialTransactionForm").closest(".page-card");
    var previewCard = screen.querySelector("#financialTransactionPreviewBox");
    var accountsCard = screen.querySelector("#financialAccountsWrapper") && screen.querySelector("#financialAccountsWrapper").closest(".page-card");
    var transactionsCard = screen.querySelector("#financialTransactionsWrapper") && screen.querySelector("#financialTransactionsWrapper").closest(".page-card");
    var costsCard = screen.querySelector("#productiveCostWrapper") && screen.querySelector("#productiveCostWrapper").closest(".page-card");

    var nav = document.createElement("div");
    nav.id = "financeiroSubnav";
    nav.className = "finance-subnav";
    nav.setAttribute("role", "tablist");
    nav.innerHTML =
      '<button type="button" class="finance-tab is-active" data-finance-view="overview" role="tab" aria-selected="true">Resumo</button>' +
      '<button type="button" class="finance-tab" data-finance-view="accounts" role="tab" aria-selected="false">Contas</button>' +
      '<button type="button" class="finance-tab" data-finance-view="transactions" role="tab" aria-selected="false">Lançamentos</button>' +
      '<button type="button" class="finance-tab" data-finance-view="costs" role="tab" aria-selected="false">Custos produtivos</button>';

    var header = screen.querySelector(".page-header");
    if (header) header.insertAdjacentElement("afterend", nav);

    var views = [
      { name: "overview", nodes: [periodCard, summary] },
      { name: "accounts", nodes: [accountFormCard, accountsCard] },
      { name: "transactions", nodes: [transactionFormCard, previewCard, transactionsCard] },
      { name: "costs", nodes: [costsCard] }
    ];

    views.forEach(function (view) {
      var panel = document.createElement("section");
      panel.className = "finance-view" + (view.name === "overview" ? " is-active" : "");
      panel.setAttribute("data-finance-panel", view.name);
      panel.setAttribute("role", "tabpanel");
      view.nodes.forEach(function (node) { if (node) panel.appendChild(node); });
      screen.appendChild(panel);
    });
  }

  function switchFinanceView(view) {
    var selected = view || "overview";
    document.querySelectorAll("#financeiroSubnav [data-finance-view]").forEach(function (button) {
      var active = button.getAttribute("data-finance-view") === selected;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-selected", active ? "true" : "false");
    });
    document.querySelectorAll("#screen-financeiro [data-finance-panel]").forEach(function (panel) {
      panel.classList.toggle("is-active", panel.getAttribute("data-finance-panel") === selected);
    });
  }

