  function getTransferCategoryOptionsHtml() {
    return '<option value="transferencia_entre_contas">Transferência entre contas</option>';
  }

  function updateStatusOptions() {
    var type = getElement("financialTransaction_type") ? getElement("financialTransaction_type").value : "expense";
    var statusSelect = getElement("financialTransaction_status");

    if (!statusSelect) {
      return;
    }

    var current = statusSelect.value;

    if (type === "income") {
      statusSelect.innerHTML =
        '<option value="pending">Conta a receber pendente</option>' +
        '<option value="received">Recebido</option>';

      statusSelect.value = current === "received" ? "received" : "pending";
      return;
    }

    if (type === "transfer") {
      statusSelect.innerHTML =
        '<option value="pending">Transferência pendente</option>' +
        '<option value="paid">Transferência realizada</option>';

      statusSelect.value = current === "paid" ? "paid" : "pending";
      return;
    }

    statusSelect.innerHTML =
      '<option value="pending">Conta a pagar pendente</option>' +
      '<option value="paid">Pago</option>';

    statusSelect.value = current === "paid" ? "paid" : "pending";
  }

  function updateCategoryOptions() {
    var type = getElement("financialTransaction_type") ? getElement("financialTransaction_type").value : "expense";
    var categorySelect = getElement("financialTransaction_category");

    if (!categorySelect) {
      return;
    }

    var current = categorySelect.value;

    if (type === "income") {
      categorySelect.innerHTML = getIncomeCategoryOptionsHtml();
    } else if (type === "transfer") {
      categorySelect.innerHTML = getTransferCategoryOptionsHtml();
    } else {
      categorySelect.innerHTML = getExpenseCategoryOptionsHtml();
    }

    if (current) {
      categorySelect.value = current;
    }

    if (!categorySelect.value) {
      categorySelect.selectedIndex = 0;
    }
  }

  function toggleTransactionFields() {
    var type = getElement("financialTransaction_type") ? getElement("financialTransaction_type").value : "expense";

    updateStatusOptions();
    updateCategoryOptions();

    if (type === "transfer") {
      setText("financialTransaction_accountLabel", "Conta de origem");
      showElement("financialTransaction_destinationField");
      hideElement("financialTransaction_supplierField");
      hideElement("financialTransaction_customerField");
    } else if (type === "income") {
      setText("financialTransaction_accountLabel", "Conta de recebimento");
      hideElement("financialTransaction_destinationField");
      hideElement("financialTransaction_supplierField");
      showElement("financialTransaction_customerField");
    } else {
      setText("financialTransaction_accountLabel", "Conta de pagamento");
      hideElement("financialTransaction_destinationField");
      showElement("financialTransaction_supplierField");
      hideElement("financialTransaction_customerField");
    }

    updateTransactionPreview();
  }

